var STONES = [{"no": 1, "id": "dukkeobi-dol", "name": "두꺼비돌", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/dukkeobi-dol-1.v3.webp", "w": 900, "h": 600}], "body": [{"p": ["이 두꺼비 바위는 50톤 짜리 형상석으로, 이름 그대로 커다란 두꺼비가 웅크리고 앉아 있는 듯한 모습을 한 형상석입니다."]}, {"p": ["2015년 월명동 자연성전에 하나님 폭포 조경을 쌓던 중, 성령님이 선물로 주신 바위입니다."]}, {"p": ["당시 폭포 조경에 사용할 돌을 찾던 중 약 50톤에 이르는 커다란 바위를 가져왔는데, 자리를 잡고 자세히 살펴보니 놀랍게도 두꺼비를 닮은 모습이었습니다."]}, {"p": ["일반적인 형상석은 한두 부분이 특정 동물과 닮아 보이는 경우가 많습니다. 그러나 이 두꺼비돌은 머리와 눈, 입은 물론이고 온몸의 오돌토돌한 돌기와 뒷다리, 불룩한 배와 볼, 엉덩이에 이르기까지 모두 여덟 가지 특징이 두꺼비의 모습과 닮아 있습니다."]}, {"p": ["이 바위는 하나님 폭포를 조성한 뒤 성령님이 이 시대를 따르는 자들 모두에게 주신 특별한 선물입니다.", "성령께서 돌을 사 올 때 옆에서 지켜보고 계시다가 얼른 치마로 싸서 가지고 오듯 하신 것입니다."]}, {"p": [{"t": "당시 사명자가 기도하는 가운데 성령께서 “사랑하는 자가 형상석을 그리도 좋아하니, 좋아하는 것을 선물로 해 줬다. 그래서 치마 찢어져 가면서 싸 가지고 왔다.”고 말씀하셨습니다.", "em": "“사랑하는 자가 형상석을 그리도 좋아하니, 좋아하는 것을 선물로 해 줬다. 그래서 치마 찢어져 가면서 싸 가지고 왔다.”"}]}, {"p": ["두꺼비돌이 한두 가지가 아니라 여러 특징에서 실제 두꺼비의 모습을 닮은 것처럼, 사람 역시 삶의 여러 부분에서 좋은 성품과 신앙의 모습을 두루 갖추어야 합니다."]}, {"p": [{"q": "“나는 하나님과 예수님의 성품을 얼마나 많이 닮았는가?”"}]}, {"p": ["여덟 가지 특징을 갖춰 누가 봐도‘두꺼비 형상이네’라고 인정받는 두꺼비돌처럼, 여러분도 모두가 인정하도록 자신의 성품과 사랑, 감사와 실천을 날마다 더해 가시길 바랍니다."]}], "i18n": {"en": {"name": "The Toad Rock", "alias": "", "body": [{"p": ["The Toad Rock is a 50-ton image rock that, as its name suggests, resembles a giant toad crouching low to the ground."]}, {"p": ["This rock was given as a gift from the Holy Spirit in 2015, during the construction of God’s Waterfall at the Wolmyeongdong Natural Temple. At the time, while searching for rocks to use in the waterfall landscaping, a massive rock weighing approximately 50 tons was brought to the site. Once it was positioned and examined more closely, it was discovered, surprisingly, that the rock resembled a toad."]}, {"p": ["Most image rocks resemble a particular animal in only one or two features. However, the Toad Rock has eight distinct features resembling those of a real toad, including its head, eyes, mouth, bumpy skin covering its entire body, hind legs, bulging belly, cheeks, and rear end."]}, {"p": ["This rock was a special gift from the Holy Spirit to all those who follow this time period, given after God’s Waterfall was completed.", "It was as though the Holy Spirit had been watching as the rock was being purchased and had quickly wrapped it in Her skirt to bring it here.", {"t": "At the time, while the Man of Mission was praying, the Holy Spirit said, “My beloved loves image rocks so much that I gave him what he loves as a gift. I wrapped it up and brought it here, even tearing my skirt in the process.”", "em": "“My beloved loves image rocks so much that I gave him what he loves as a gift. I wrapped it up and brought it here, even tearing my skirt in the process.”"}]}, {"p": ["Just as the Toad Rock resembles a real toad in many features rather than just one or two, we too should develop good character and faith in every aspect of our lives."]}, {"p": [{"q": "“How much am I becoming like God and Jesus in my character?”"}]}, {"p": ["Just as the Toad Rock has eight distinct features that make anyone recognize it as the shape of a toad, may you continue to develop your character, love, gratitude, and actions each day so that these qualities will be recognized by everyone."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/dukkeobi-dol.en.v1.m4a", "audioDur": 151.5}, "ja": {"name": "ヒキガエルの岩", "alias": "", "body": [{"p": ["このヒキガエルの岩は50トンの形象石で、その名のとおり、大きなヒキガエルがうずくまって座っているような姿をした形象石です。"]}, {"p": ["2015年、月明洞自然聖殿に神様の滝の造景を築いていた際、聖霊様が贈り物としてくださった岩です。"]}, {"p": ["当時、滝の造景に使用する石を探していたところ、約50トンに達する大きな岩を運んできました。所定の位置に据えて詳しく見てみると、驚くことにヒキガエルに似た姿をしていました。"]}, {"p": ["一般的な形象石は、一つか二つの部分が特定の動物に似て見える場合が多くあります。しかし、このヒキガエルの岩は、頭と目、口はもちろん、全身のごつごつとした突起や後ろ足、膨らんだ腹や頬、お尻に至るまで、全部で八つの特徴がヒキガエルの姿と似ています。"]}, {"p": ["この岩は、神様の滝を造成した後、聖霊様がこの時代に従うすべての人々にくださった特別な贈り物です。"]}, {"p": ["聖霊様が石を買ってくるときにそばで見守っておられ、さっとスカートに包んで持ってこられたかのようなものです。"]}, {"p": [{"t": "当時、使命者が祈る中で、聖霊様は「愛する者が形象石をとても好きなので、好きなものをプレゼントしてあげた。それで、スカートが破れるほど包んで持ってきた」とおっしゃいました。", "em": "「愛する者が形象石をとても好きなので、好きなものをプレゼントしてあげた。それで、スカートが破れるほど包んで持ってきた」"}]}, {"p": ["ヒキガエルの岩が一つや二つではなく、さまざまな特徴において実際のヒキガエルの姿に似ているように、人もまた、人生のさまざまな部分において、良い品性と信仰の姿をまんべんなく備えなければなりません。"]}, {"p": [{"q": "「私は神様とイエス様の品性に、どれほど似ているだろうか？」"}]}, {"p": ["八つの特徴を備え、誰が見ても「ヒキガエルの形象だ」と認めるヒキガエルの岩のように、皆さんも誰もが認めるほど、自分の品性と愛、感謝と実践を日々さらに加えていくことを願います。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/dukkeobi-dol.ja.v2.m4a", "audioDur": 171.0}, "zh": {"name": "蟾蜍石", "alias": "", "body": [{"p": ["這蟾蜍石是重量約50噸的形像石，它的外形正如其名，宛如一隻巨大的蟾蜍壓低身子蹲著。"]}, {"p": ["2015年在月明洞自然聖殿進行　神的瀑布造景過程中，聖靈送給我們這顆石頭。", "當時為了尋找瀑布造景需用的石材，而運來了這顆重量約50噸的大岩石。在放置好後仔細觀看，便驚人地發現這顆石頭具有相似於蟾蜍的形像。"]}, {"p": ["一般的形像石往往只有一兩個地方相似於特定動物，但這顆蟾蜍石不僅頭部、眼睛、嘴巴，還有如蟾蜍皮膚般一粒粒隆起的疣，以及後腿、鼓起的腹部、臉頰與臀部，總共有八個特徵相似於蟾蜍。"]}, {"p": ["這顆蟾蜍石，是　神的瀑布完工後，聖靈賜給所有跟隨這時代之人的特別禮物。", "當初把這顆石頭買回來時，聖靈就在一旁觀看，彷彿是盡快用裙子包住帶回來一般。", {"t": "當初使命者禱告時，聖靈說：「既然我心愛的人那麼喜歡形像石，我想送心愛之人喜歡的東西，這才扯破裙子把它包住帶回來了。」", "em": "「既然我心愛的人那麼喜歡形像石，我想送心愛之人喜歡的東西，這才扯破裙子把它包住帶回來了。」"}]}, {"p": ["蟾蜍石不只具備一兩個特徵，它在各方面都相似於真的蟾蜍；同樣地，人也要在各個面向都具備美好的品性與信仰樣貌。"]}, {"p": [{"q": "「我有多麼相似於　神與耶穌的品性呢？」"}]}, {"p": ["蟾蜍石有八個特徵，任誰看了都會認定「是蟾蜍形像！」，如此一般，希望各位的品性、愛、感謝與實踐也能日益增加，讓自己能得到所有人的認定。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/dukkeobi-dol.zh.v1.m4a", "audioDur": 157.3}}, "audio": "/sayeon/stones/audio/45-guide.mp3", "audioDur": 169.9}, {"no": 2, "id": "33ton-bawi", "name": "33톤 바위", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/33ton-bawi-1.v3.webp", "w": 900, "h": 600}], "body": [{"p": ["이 바위는 무게가 약 33톤에 이르러 ‘33톤바위’, 또는 ‘33바윗돌’이라고 불립니다. ‘33’이라는 숫자는 예수님의 33년 생애를 떠올리게 합니다. 또한 선생님이 예수님에게  새 시대의 말씀을 배우고 수도생활을 해온 33년의 세월을 상징하기도 합니다."]}, {"p": ["본래 이 바위는 마을에서 약 300m 떨어진 산기슭, 지금의 조산과 ‘성자 사랑의 집’이 자리한 일대에 있었습니다. 선생님은 어린 시절 형제자매들과 함께 이 바위에 올라 주변에 자라던 포도머루를 따 먹곤 했습니다."]}, {"p": ["이후 월명동 자연성전을 개발하면서 이 바위는 여러 차례 자리를 옮겼습니다. 그 과정에서 하나님의 은밀한 보호하심 가운데 여러 고비를 지나, 지금의 자리에 놓이게 된 남다른 사연을 지닌 바위입니다."]}], "i18n": {"en": {"name": "The 33-ton Rock", "alias": "", "body": [{"p": ["This rock weighs approximately 33 tons and is known as “The 33-Ton Rock” or “The 33 Boulder.” The number 33 reminds us of the 33 years of Jesus' life on earth. It also symbolizes the 33 years that Seonsaengnim spent in spiritual training, learning the Word of the new time period from Jesus."]}, {"p": ["Originally, this rock was located on a mountainside about 300 meters from the village, in the area where Morning Hill and the Holy Son's House of Love now stand.", "During his childhood, Seonsaengnim would climb onto this rock with his siblings and pick and eat wild grapes growing nearby."]}, {"p": ["Later, during the development of the Wolmyeongdong Natural Temple, the rock was moved several times. It has a remarkable story of overcoming numerous challenges under God's unseen protection before finally being placed in its present location."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/33ton-bawi.en.v1.m4a", "audioDur": 96.5}, "ja": {"name": "33トン岩", "alias": "", "body": [{"p": ["この岩は重さが約33トンに達することから、「33トン岩」、または「33岩石」と呼ばれています。「33」という数字は、イエス様の33年間の生涯を思い起こさせます。また、先生がイエス様から新時代の御言葉を学び、修道生活をしてきた33年間の歳月を象徴してもいます。"]}, {"p": ["もともとこの岩は、村から約300メートル離れた山裾、現在のチョサンと「御子愛の家」がある一帯にありました。", "先生は幼い頃、兄弟姉妹と一緒にこの岩に登り、周辺に実っていた山ぶどうを採って食べたりしていました。"]}, {"p": ["その後、月明洞自然聖殿を開発する中で、この岩は何度か場所を移しました。その過程で、神様の密かな守りの中、幾度もの困難を乗り越え、現在の場所に置かれるようになった特別な経緯を持つ岩です。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/33ton-bawi.ja.v2.m4a", "audioDur": 110.7}, "zh": {"name": "33噸石", "alias": "", "body": [{"p": ["這顆石頭是重量約33噸的「三十三噸石」，也被稱為「三十三石」。「三十三」這個數字，讓人聯想到耶穌三十三年的生涯，也象徵老師向耶穌學習新時代話語、度過修道生活的三十三年歲月。"]}, {"p": ["原本它位於距離村子約300公尺遠的山腳下，也就是如今的朝山與「聖子愛之家」一帶。", "老師年幼時常與兄弟姊妹爬上這顆石頭，採集周圍生長的野葡萄來吃。"]}, {"p": ["之後，在開發月明洞自然聖殿的過程中，這顆石頭曾多次被移動。它在　神隱密的保守之下，經歷層層關卡，最終安置在如今的位置。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/33ton-bawi.zh.v1.m4a", "audioDur": 100.2}}, "audio": "/sayeon/stones/audio/23-guide.mp3", "audioDur": 102.3}, {"no": 3, "id": "horangi-dol", "name": "호랑이 바위", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/horangi-dol-1.v3.webp", "w": 900, "h": 600}], "body": [{"p": ["호랑이 바위는 한 마리의 용맹한 호랑이가 웅크리고 있는 듯한 형상을 지닌 자연석입니다."]}, {"p": ["이 바위는 선생님이 생가 인근 논골 골짜기에서 소나무 작업을 하던 당시 항상 눈에 띄었습니다. 어느 날 선생님은 돌을 빼러가자는 예수님의 감동을 받고, 평소 눈여겨보던 그 바위를 포클레인으로 빼냈습니다."]}, {"p": ["바위를 처음 꺼냈을 때는 겉모습이 마치 썩은 돌처럼 볼품없어 보였습니다. 그대로 두고 갈까도 했지만, 이끼와 흙을 걷어내고 물로 깨끗이 씻어내자 호랑이를 닮은 모습이 선명하게 나타났습니다."]}, {"p": ["호랑이 바위엔 호랑이의 다부진 턱과 윗니, 눈의 형상을 찾아볼 수 있습니다. 몸통에는 표범 무늬를 닮은 자연스러운 표면이 이어지고, 몸을 감싸는 듯한 꼬리 형상도 있습니다."]}, {"p": ["호랑이 바위는 겉모습만 보고 가치를 판단하기보다, 끝까지 확인해야 참된 가치가 드러난다는 깊은 메시지를 전합니다."]}], "i18n": {"en": {"name": "The Tiger Rock", "alias": "", "body": [{"p": ["The Tiger Rock is a natural rock resembling a fierce tiger crouching down."]}, {"p": ["This rock had always caught Seonsaengnim's attention whenever he worked with pine trees in the Nongol Valley near his birthplace. One day, inspired by Jesus to go and excavate the rock, Seonsaengnim used an excavator to extract the rock he had long had his eye on."]}, {"p": ["When the rock was first excavated, its outward appearance was unappealing, as though it were a decaying stone. Seonsaengnim considered leaving it behind. However, once the moss and soil were removed and the rock was thoroughly washed with water, its resemblance to a tiger became clearly visible."]}, {"p": ["The Tiger Rock has formations resembling a tiger’s sturdy jaw, upper teeth, and eyes. Its body has natural surface patterns resembling a leopard’s spots, as well as a tail-like formation that appears to wrap around its body."]}, {"p": ["The Tiger Rock conveys a profound message: rather than judging something’s value by its outward appearance alone, we must examine it thoroughly to reveal its true value."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/horangi-dol.en.v1.m4a", "audioDur": 97.7}, "ja": {"name": "虎の岩", "alias": "", "body": [{"p": ["虎の岩は、一頭の勇猛な虎がうずくまっているかのような形象を持つ自然石です。"]}, {"p": [{"t": "この岩は、先生が生家近くのノンコルの谷で松の作業をしていた当時、いつも目に留まっていました。ある日、先生は「岩を取り出しに行こう」というイエス様からの感動を受け、以前から目を留めていたその岩をショベルカーで掘り出しました。", "em": "「岩を取り出しに行こう」"}]}, {"p": ["岩を初めて取り出した時は、表面がまるで腐った石のようで、見栄えがよくありませんでした。そのまま置いていこうかとも思いましたが、苔や土を取り除き、水できれいに洗い流すと、虎に似た姿がはっきりと現れました。"]}, {"p": ["虎の岩には、虎のがっしりとした顎や上の歯、目の形象を見ることができます。胴体にはヒョウ柄を思わせる自然な模様が広がり、体を包み込むような尾の形象もあります。"]}, {"p": ["虎の岩は、外見だけを見て価値を判断するのではなく、最後まで確認してこそ真の価値が現れるという深いメッセージを伝えています。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/horangi-dol.ja.v2.m4a", "audioDur": 114.7}, "zh": {"name": "老虎石", "alias": "", "body": [{"p": ["老虎石是一顆自然石，酷似一隻勇猛的老虎蜷伏著身體。"]}, {"p": [{"t": "以前老師到老家附近的田谷進行松樹工程時，每次都會被這顆岩石吸引。有一天，耶穌感動老師說：「我們去把石頭挖出來吧！」於是便用挖土機，將這顆一直留意的石頭從土裡拔了出來。", "em": "「我們去把石頭挖出來吧！」"}]}, {"p": ["剛挖出來時，石頭的外表像一顆腐朽的石頭，毫不起眼，本來打算直接棄置。但是，把上面的苔蘚和泥土清除，再用水沖洗乾淨之後，如老虎般的形像便清楚地顯現出來了。"]}, {"p": ["老虎石上可以看見老虎結實有力的下顎與上獠牙，以及一雙眼睛；也可以在它身體表面看出非常自然的虎紋，甚至還有繞著身體的尾巴。"]}, {"p": ["老虎石要傳遞的深刻訊息是，比起只看表面就判斷價值，更應當看到最後、確認到底，才會看出真正的價值。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/horangi-dol.zh.v1.m4a", "audioDur": 120.0}}, "audio": "/sayeon/stones/audio/13-guide.mp3", "audioDur": 114.6}, {"no": 4, "id": "seongja-bawi", "name": "성자바위", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/seongja-bawi-1.v3.webp", "w": 800, "h": 533}], "body": [{"p": ["성자바위는 삼위일체 신 중 한 분이신‘성자’를 상징하는 바위입니다. 성자가 주신 바위이자, 성자의 형상을 갖췄기에 그같은 명칭으로 부르게 되었습니다. 무게는 약 130톤, 높이 약 4m× 길이 약 6m × 둘레 약 16m에 이르는 거대한 자연석입니다."]}, {"p": ["이 바위는 바라보는 각도에 따라 무려 6가지 다른 형상이 나타나는 것이 특징입니다. 한 돌이 한 형상을 갖추기도 어려운데, 무려 여섯 형상이나 갖춘 신비한 구상의 자연석입니다."]}, {"p": ["성자바위의 정면에는 날렵한 눈과 우뚝 솟은 부리가 돋보이는 인(人)독수리 얼굴이 존재합니다. 좌측 측면엔 근엄하고 위엄있는 성자의 얼굴이 뚜렷이 있습니다.", "두 얼굴이 합쳐진 면에는 하나님 상징의 얼굴 형상이 근엄하게 있습니다. 또한 후면에는 성령님을 상징하는 긴 머리의 여성 두상이 있습니다."]}, {"p": ["그 외에도 전투기 팬텀기의 형상, 발바닥 형상도 찾아볼 수 있습니다. 붉은 기가 도는 '발바닥'형상은 성경 말씀대로 성자의 희생, 거룩함을 상징합니다. '이곳은 거룩한 곳이니 네 발의 신을 벗어라. 이 돌은 거룩한 바위다.'라는 뜻도 담고 있습니다.", "성자바위가 이 세상에 드러나게 된 계기는 2012년 10월이었습니다. 선생님은 10월 돌축제를 앞두고 월명동에 찾아오는 사람들에게 희망을 줄 새로운 돌을 찾고자 21일간 기도하던 중이었습니다."]}, {"p": ["마땅한 돌을 구하지 못하던 가운데, 명막골의 한 논에 일부만 드러나 있던 바위를 파내게 되었습니다. 이 바위는 선생님이 10대 시절 친척집을 오가며 올라가 놀고, 바위 위에 자라는 돌나물을 따오곤 했던 곳이었습니다.평소에는 작은 바위처럼 보였지만 땅을 파내자 예상보다 훨씬 큰 바위가 모습을 드러냈습니다."]}, {"p": ["이처럼 오랜 사연이 있는 바위가 훗날 월명동 자연성전의 걸작품 바위로 드러났기에 더욱 깊은 사연을 지니고 있습니다.", "또한 바로 옆의 104톤 ‘큰바위얼굴’과 함께 월명동을 대표하는 대형 형상석이기도 합니다."]}], "i18n": {"en": {"name": "The Holy Son Rock", "alias": "", "body": [{"p": ["The Holy Son Rock symbolizes the Holy Son, one of the three divine beings of the Trinity. It was given this name because it was a gift from the Holy Son and bears His likeness.", "It is a massive natural rock, weighing approximately 130 tons, standing about 4 meters tall, measuring 6 meters in length, and having a circumference of approximately 16 meters."]}, {"p": ["One of the most remarkable features of this rock is that it reveals six distinct images depending on the angle from which it is viewed. While it is difficult for a single rock to have even one recognizable image, this mysterious natural rock has as many as six distinct images."]}, {"p": ["On the front of the Holy Son Rock, you can find the face of a human-eagle, distinguished by its sharp eyes and prominent beak. On the left side, the solemn and majestic face of the Holy Son is clearly visible."]}, {"p": ["Where these two faces meet, there is another solemn face symbolizing God. On the back of the rock, you can also find the shape of the head of a long-haired woman who symbolizes the Holy Spirit."]}, {"p": [{"t": "In addition, the rock features images resembling a Phantom fighter jet and the sole of a foot. The reddish sole-shaped image symbolizes the Holy Son's sacrifice and holiness, as described in the Bible. It also conveys the message, “Take off your sandals, for this is holy ground. This rock is sacred.”", "em": "“Take off your sandals, for this is holy ground. This rock is sacred.”"}]}, {"p": ["The story of how the Holy Son Rock was revealed to the world began in October 2012. Ahead of the October Rock Festival, Seonsaengnim had been praying for 21 days to find a new rock that would bring hope to those visiting Wolmyeongdong."]}, {"p": ["While he was still searching for a suitable rock, he began excavating a rock that was partially exposed in a rice field in Myeongmakgol. This rock held special memories for Seonsaengnim. During his teenage years, he would climb onto it and play while traveling to and from his relatives' home. He would also pick stonecrop growing on top of the rock."]}, {"p": ["Although it had always appeared to be a relatively small rock, excavation revealed that it was far larger than expected."]}, {"p": ["The fact that this rock, which held so many memories from long ago, was eventually revealed as a masterpiece of the Wolmyeongdong Natural Temple makes its story all the more meaningful.", "Together with the nearby 104-ton “Great Stone Face” Rock, it is also one of the large image rocks that represent Wolmyeongdong."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/seongja-bawi.en.v1.m4a", "audioDur": 164.5}, "ja": {"name": "御子岩", "alias": "", "body": [{"p": ["御子岩は、三位一体の神のうちのお一方である「御子」を象徴する岩です。御子がくださった岩であり、御子の形象を備えていることから、そのような名称で呼ばれるようになりました。"]}, {"p": ["重さは約130トン、高さ約4メートル×長さ約6メートル×周囲約16メートルに達する巨大な自然石です。"]}, {"p": ["この岩は、見る角度によって、実に6種類の異なる形象が現れることが特徴です。一つの石が一つの形象を備えることさえ難しい中、実に六つもの形象を備えた神秘的な構想の自然石です。"]}, {"p": ["御子岩の正面には、鋭い目と高く突き出たくちばしが際立つ人鷲の顔があります。左側面には、厳かで威厳のある御子の顔がはっきりとあります。"]}, {"p": ["二つの顔が重なる面には、神様を象徴する厳かな顔の形象があります。また、裏面には聖霊様を象徴する長い髪の女性の頭部があります。"]}, {"p": [{"t": "そのほかにも、戦闘機ファントムの形象や足の裏の形象を見つけることができます。赤みを帯びた「足の裏」の形象は、聖書の御言葉のとおり、御子の犠牲と神聖を象徴しています。「ここは聖なる場所だから、あなたの足の履物を脱ぎなさい。この石は聖なる岩だ」という意味も込められています。", "em": "「ここは聖なる場所だから、あなたの足の履物を脱ぎなさい。この石は聖なる岩だ」"}]}, {"p": ["御子岩がこの世に姿を現すことになったきっかけは、2012年10月でした。先生は10月の岩の祝祭を前に、月明洞を訪れる人々に希望を与える新しい石を探そうと、21日間祈っていました。"]}, {"p": ["ふさわしい石を見つけられずにいた中、ミョンマッコルのある田んぼに一部だけ姿を現していた岩を掘り出すことになりました。この岩は、先生が10代の頃、親戚の家を行き来しながら登って遊んだり、岩の上に生えているツルマンネングサを採ったりしていた場所でした。"]}, {"p": ["普段は小さな岩のように見えていましたが、地面を掘り進めると、予想よりはるかに大きな岩が姿を現しました。"]}, {"p": ["このように長い経緯を持つ岩が、後に月明洞自然聖殿の傑作品となる岩として姿を現したため、より深い経緯が込められています。"]}, {"p": ["また、すぐ隣にある104トンの「大いなる岩の顔の岩」と共に、月明洞を代表する大型形象石でもあります。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/seongja-bawi.ja.v2.m4a", "audioDur": 171.6}, "zh": {"name": "聖子石", "alias": "", "body": [{"p": ["聖子石是象徵三位一體神當中的「聖子」的石頭。由於是聖子賜下的石頭，同時也具備聖子的形像，所以才如此命名。", "這顆石頭重量約130噸、高度約4公尺、寬度約6公尺、周長約16公尺，是巨大的自然石。"]}, {"p": ["它的最大特色，就是根據觀看者觀看的角度，能看出六種不同的形像。一顆石頭就連要具備一種形像都很不容易，而它竟然具備了六種形像，是依照神祕的構想形成的自然石。"]}, {"p": ["聖子石的正面有一張「人老鷹」臉龐，銳利的眼睛和高聳的喙格外顯眼的。左側有一張既莊嚴又有威嚴的聖子臉龐。"]}, {"p": ["在兩張臉銜接面，有一個象徵　神的威嚴臉龐形像。背面則有象徵聖靈的女性頭形。"]}, {"p": [{"t": "此外，還找得到幽靈戰鬥機的形像、腳掌形像。自帶朱紅色的「腳掌」形像，如聖經話語所述，象徵的是聖子的犧牲與聖潔。還帶有「把你腳上的鞋脫下來，因為你所站之地是聖地。這顆石頭是聖潔的石頭」的意思。", "em": "「把你腳上的鞋脫下來，因為你所站之地是聖地。這顆石頭是聖潔的石頭」"}]}, {"p": ["聖子石公開亮相的時間為2012年10月。老師想要在該年十月的石頭慶典找到全新的石頭，帶給拜訪月明洞的人希望，為此進行著為期二十一天的禱告。"]}, {"p": ["然而，卻遲遲找不到適合的石頭。後來試著挖掘一顆位於明幕谷、只露出一小角的石頭。這顆石頭是老師在十幾歲時，往返親戚家的路途中會爬上去玩耍，還會爬上去採摘垂盆草的石頭。"]}, {"p": ["挖掘出來後發現，平常看來以為很小的石頭，在地面下埋藏的部分竟然巨大得超乎預期。"]}, {"p": ["這顆蘊含悠久故事的石頭如此被挖掘，成為日後月明洞自然聖殿的傑作石，使得其中的故事更為深刻。它與旁邊的104噸「人面巨石」，是月明洞最具代表性的大型形像石。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/seongja-bawi.zh.v1.m4a", "audioDur": 183.5}}, "audio": "/sayeon/stones/audio/1-guide.mp3", "audioDur": 176.6}, {"no": 5, "id": "gido-bawi", "name": "기도바위", "alias": "성령바위", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/gido-bawi-1.v3.webp", "w": 800, "h": 534}], "body": [{"p": ["기도바위는 열 명 이상이 앉을 수 있을 만큼 넓고 평평한 납작돌입니다. 동시에 무게 약 65톤의 육중한 크기를 자랑합니다. 또한 매끄럽고 부드러운 형상 때문에 ‘성령바위’라고도 불립니다."]}, {"p": ["2002년 10월, 선생님은 홍콩에서 해외선교를 하며 인터넷으로 돌조경을 감독하고 계셨습니다. 선생님이 기도하시던 중 예수님께서 ‘주차장 감나무 밑에 보물이 있다’고 말씀하셨습니다."]}, {"p": ["일주일 뒤 선생님은 큰바위얼굴을 가지러 내려가던 제자들에게 그 말씀을 전하셨습니다. 이에 제자들이 월명동 인근 주차장 감나무 밑을 확인하자, 황금빛 호박돌이 거북이 머리처럼 빼죽 나와있었습니다. 흙을 파내자 상상할 수 없던 거대한 크기의 바위가 세상에 드러났습니다.", "당시 선생님과 현장의 제자들은 몸이 멀리 떨어져 있어 마음을 다 전달하기 어려웠던 상황이었습니다. 그러나 예수님이 함께하시어 작업을 이끌어주셨고 하늘 앞에 기도드린 정성이 있었기에 시공간을 초월해 불가능을 가능케 했습니다."]}], "i18n": {"en": {"name": "The Prayer Rock", "alias": "The Holy Spirit Rock", "body": [{"p": ["The Prayer Rock is a broad, flat rock large enough to seat more than ten people. It is also massive, weighing approximately 65 tons. Because of its smooth, gently contoured form, it is also known as the Holy Spirit Rock."]}, {"p": [{"t": "In October 2002, Seonsaengnim was carrying out overseas missionary work in Hong Kong while supervising the rock landscaping work in Wolmyeongdong via the internet. While he was praying, Jesus told him, “There is a treasure beneath the persimmon tree in the parking lot.”", "em": "“There is a treasure beneath the persimmon tree in the parking lot.”"}]}, {"p": ["A week later, Seonsaengnim relayed these words to his disciples, who were on their way to retrieve “the Great Stone Face” Rock. When they checked beneath the persimmon tree in a parking lot near Wolmyeongdong, they found a golden-colored, amber-like rock protruding from the ground like a turtle's head. As they dug away the soil, an unimaginably enormous rock was revealed."]}, {"p": ["At the time, Seonsaengnim and the disciples working at the site were physically far apart, making it difficult for him to fully convey his thoughts to them. However, because Jesus was with them and guided the work, and because of their sincere prayers to Heaven, they were able to transcend the limitations of time and space and make the impossible possible."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/gido-bawi.en.v1.m4a", "audioDur": 111.0}, "ja": {"name": "祈りの岩", "alias": "聖霊岩", "body": [{"p": ["祈りの岩は、10人以上が座れるほど広く平らな板状の岩です。同時に、重さ約65トンにもなる巨大な岩です。また、滑らかで柔らかな形象をしていることから、「聖霊岩」とも呼ばれています。"]}, {"p": [{"t": "2002年10月、先生は香港で海外宣教をしながら、インターネットを通して岩の造景を監督していました。先生が祈っていたところ、イエス様が「駐車場の柿の木の下に宝がある」とおっしゃいました。", "em": "「駐車場の柿の木の下に宝がある」"}]}, {"p": ["一週間後、先生は大いなる岩の顔の岩を取りに向かっていた弟子たちに、その御言葉を伝えました。そこで弟子たちが月明洞近くの駐車場にある柿の木の下を確認すると、黄金色の琥珀石が亀の頭のようにひょっこりと突き出ていました。土を掘り出すと、想像もできなかったほど巨大な岩がその姿を現しました。"]}, {"p": ["当時、先生と現場にいた弟子たちは遠く離れていたため、先生の思いを十分に伝えることが難しい状況でした。しかし、イエス様が共にして作業を導いてくださり、天の前に捧げた祈りと真心があったからこそ、時空を超えて不可能を可能にすることができました。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/gido-bawi.ja.v2.m4a", "audioDur": 129.4}, "zh": {"name": "禱告石", "alias": "聖靈石", "body": [{"p": ["禱告石是一顆寬大平坦的扁平石，可同時讓十幾個人坐在上面；重量為65噸，十分有分量。此外，因為表面平滑柔和，所以也被稱為「聖靈石」。"]}, {"p": [{"t": "2002年10月，當時老師正在香港進行海外宣教，透過網路遠距監督月明洞的石頭造景工程。在老師禱告時，耶穌說：「在停車場的柿子樹下方，有一個寶物。」", "em": "「在停車場的柿子樹下方，有一個寶物。」"}]}, {"p": ["一週後，當弟子們要前往月明洞附近的石幕里將人面巨石運回時，老師轉述了這句話。弟子們便前往月明洞附近的停車場柿子樹，在下面尋找了一番，結果發現一顆金黃色的圓石，像烏龜的頭一樣微微探出。挖出周圍泥土後，一顆遠超想像的巨大石頭終於出土。"]}, {"p": ["當時在現場施工的弟子與老師分隔兩地，難以完全傳遞心意。然而，耶穌同在並引導整個工程，加上弟子們在天面前獻上禱告的精誠，才能超越時空，讓不可能的事情化為可能。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/gido-bawi.zh.v1.m4a", "audioDur": 123.2}}, "audio": "/sayeon/stones/audio/33-guide.mp3", "audioDur": 118.4}, {"no": 6, "id": "keunbawi-eolgul", "name": "큰바위얼굴", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/keunbawi-eolgul-1.v3.webp", "w": 800, "h": 533}], "body": [{"p": ["‘큰바위얼굴’은 무게가 약 104톤에 이르는 거대한 형상석으로, 2002년 10월 10일 월명동 자연성전으로 옮겨졌습니다. 눈·코·입이 뚜렷한 사람의 얼굴을 닮았으며, 바라보는 각도에 따라 서로 다른 형상이 드러나는 것이 특징입니다."]}, {"p": ["이 바위를 월명동에 세운 뒤 자세히 살펴보니 의지가 굳고 근엄한 사람의 얼굴 형상이 드러났습니다. 이 형상은 ‘성경의 전설을 이루는 주인공’을 상징합니다."]}, {"p": ["특히 이 바위에서는 각도를 달리 하여 보면 두 개의 사람 얼굴 형상을 찾아볼 수 있습니다. 하나는 '큰바위 얼굴의 전설을 이룰 주인공'의 성장기 얼굴이고, 다른 하나는 '성장하여 마침내 뜻을 이룬 얼굴'입니다."]}, {"p": ["이 바위와의 인연은 선생님이 초등학생이던 시절로 거슬러 올라갑니다. 석막리의 한 논에 박혀 있던 이 바위를 발견했습니다. 선생님은 크고 넓죽한 바위 위에 올라가 가을이면 감을 따 먹기도 했고, 돌 위에 앉아서 놀기도 했습니다.", {"t": "어린 선생님은 ‘언젠가 저 바위를 꼭 캐 가야지’란 꿈을 품고 논 주인에게 “커서 꼭 캐 가겠다”고 말했습니다. 논 주인은 너무 큰 돌이라 실제로 가져갈 수 있겠느냐며 웃었지만, 가져갈 수 있다면 주겠다고 약속했습니다.", "em": "“커서 꼭 캐 가겠다”"}]}, {"p": ["세월이 흘러 월명동 개발이 진행되던 2002년, 어린 시절의 그 바위를 다시 떠올리게 되었습니다. 논 주인에게 당시의 이야기를 전하자 그는 옛 약속대로 바위를 내주었습니다.", "하나님과 성자께서 앞날을 두고 미리 예비해 주신 돌이었던 것입니다.", "큰바위얼굴은 인근의 ‘성자바위’와 한 쌍을 이루는 바위이기도 합니다. 성자바위가 ‘하늘의 성자바위’라면 큰바위얼굴을 ‘땅의 성자바위’라고도 부릅니다."]}], "i18n": {"en": {"name": "“The Great Stone Face” Rock", "alias": "", "body": [{"p": ["The Great Stone Face is a massive image rock weighing approximately 104 tons. It was moved to the Wolmyeongdong Natural Temple on October 10, 2002. It resembles a human face with clearly defined eyes, nose, and mouth, and reveals different images depending on the angle from which it is viewed."]}, {"p": ["After the rock was placed in Wolmyeongdong, a closer examination revealed the solemn face of a person with strong determination. This image symbolizes “the legendary figure who fulfills the biblical legend.”"]}, {"p": ["In particular, two distinct human faces can be found in this rock when viewed from different angles. One represents the face of the protagonist during his years of growth, destined to fulfill the legend of the Great Stone Face, while the other depicts his face after he has grown and finally fulfilled the will."]}, {"p": ["Seonsaengnim's connection with this rock dates back to his elementary school days, when he discovered it embedded in a rice field in Seongmak-ri. He would climb onto this large, flat rock, pick and eat persimmons in autumn, and sit and play on it."]}, {"p": ["As a child, Seonsaengnim dreamed of someday digging up the rock and taking it with him. He even told the owner of the rice field, “When I grow up, I'll definitely come back and dig up this rock.”", "The owner laughed, doubting that he could actually move such an enormous rock, but promised to give it to him if he could manage to take it away."]}, {"p": ["Years later, in 2002, while the development of Wolmyeongdong was underway, Seonsaengnim remembered the rock from his childhood. When he reminded the owner of their conversation, the owner honored his promise and gave him the rock.", "It was a rock that God and the Holy Son had prepared in advance, knowing what the future would bring."]}, {"p": [{"q": "“The Great Stone Face” Rock also forms a pair with the nearby Holy Son Rock. While the Holy Son Rock is known as “the Heavenly Holy Son Rock,” “the Great Stone Face” Rock is also called “the Earthly Holy Son Rock.”"}]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/keunbawi-eolgul.en.v1.m4a", "audioDur": 151.5}, "ja": {"name": "大いなる岩の顔の岩", "alias": "", "body": [{"p": ["「大いなる岩の顔の岩」は、重さ約104トンに達する巨大な形象石で、2002年10月10日に月明洞自然聖殿へ運ばれました。目・鼻・口がはっきりとした人の顔に似ており、見る角度によって異なる形象が現れることが特徴です。"]}, {"p": ["この岩を月明洞に立てた後、詳しく見てみると、意志が強く厳かな人の顔の形象が現れました。"]}, {"p": ["この形象は、「聖書の伝説を成し遂げる主人公」を象徴しています。"]}, {"p": ["特にこの岩は、見る角度を変えると、二つの人の顔の形象を見つけることができます。一つは「大いなる岩の顔の伝説を成し遂げる主人公」の成長期の顔で、もう一つは「成長して、ついに御心を成し遂げた顔」です。"]}, {"p": ["この岩との縁は、先生が小学生だった頃にさかのぼります。石幕里のある田んぼに埋まっていたこの岩を発見しました。先生は大きく平たい岩の上に登り、秋になると柿を採って食べたり、岩の上に座って遊んだりしていました。"]}, {"p": [{"t": "幼い先生は、「いつか、あの岩を必ず掘り出して持っていこう」という夢を抱き、田んぼの持ち主に「大きくなったら必ず掘り出して持っていく」と言いました。", "em": "「いつか、あの岩を必ず掘り出して持っていこう」"}]}, {"p": ["田んぼの持ち主は、あまりにも大きな石なので本当に持っていけるのかと笑いましたが、持っていけるならあげると約束しました。"]}, {"p": ["歳月が流れ、月明洞の開発が進められていた2002年、幼い頃のあの岩を再び思い出しました。田んぼの持ち主に当時の話を伝えると、昔の約束どおり岩を譲ってくれました。"]}, {"p": ["神様と御子が将来のために、あらかじめ備えてくださった岩だったのです。"]}, {"p": ["大いなる岩の顔の岩は、近くにある「御子岩」と一対を成す岩でもあります。御子岩が「天の御子岩」なら、大いなる岩の顔の岩は「地の御子岩」とも呼ばれています。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/keunbawi-eolgul.ja.v2.m4a", "audioDur": 174.8}, "zh": {"name": "人面巨像石", "alias": "", "body": [{"p": ["人面巨石是重量約104噸的巨大形像石，在2002年10月10日被搬到月明洞自然聖殿。人面巨石的特色在於，其形像酷似一張眼睛、鼻子、嘴巴都十分清晰的人臉，而從不同的角度觀看，又會呈現截然不同的形像。"]}, {"p": ["將這石頭豎立在月明洞後仔細觀察，就看見一張意志堅定又有威嚴的人臉形像。", "這形像象徵「達成聖經傳說的主角」。"]}, {"p": ["更特別的是，從不同的角度觀看，能在這顆石頭上看見兩張不同的人臉。一張是「即將達成人面巨石傳說的主角」在成長時期的樣貌，另一張是他「在成長後終於達成旨意」的樣貌。"]}, {"p": ["老師跟這顆石頭的緣分可以追溯到小學時期，老師在石幕里的某塊田裡發現了這顆石頭。老師會爬到寬大平坦的石頭上，秋天則會摘柿子來吃，也常在石頭上玩耍。"]}, {"p": [{"t": "年幼的老師心中萌生了一個夢想：「總有一天一定要把這顆石頭搬走。」甚至對田地主人說：「我長大後一定會把這顆石頭挖走。」", "em": "「我長大後一定會把這顆石頭挖走。」"}, {"t": "田主笑著說：「這麼大的石頭，你真的搬得走嗎？」然後答應老師：「你若能搬走，就送給你。」", "em": "「這麼大的石頭，你真的搬得走嗎？」"}]}, {"p": ["之後過了一段歲月，來到如火如荼地開發月明洞的2002年。老師再次想起童年的那顆石頭，便向田主提起當年的約定。田主也遵守多年前的承諾，把石頭送給老師。", "這顆石頭是　神與聖子瞭解未來、提早預備的石頭。"]}, {"p": ["這顆人面巨石，與鄰近的「聖子石」形成一對。若將聖子石稱為「天上的聖子石」，那麼人面巨石便可稱為「地上的聖子石」。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/keunbawi-eolgul.zh.v1.m4a", "audioDur": 177.8}}, "audio": "/sayeon/stones/audio/2-guide.mp3", "audioDur": 178.8}, {"no": 7, "id": "kokkiri-bawi", "name": "코끼리바위", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/kokkiri-bawi-1.v3.webp", "w": 900, "h": 600}], "body": [{"p": ["코끼리는 육지에서 가장 큰 동물로, 예로부터 힘과 위엄을 상징해 왔습니다."]}, {"p": ["이 바위를 처음 가져올 당시 돌 회사 사장을 비롯한 모두가 ‘두꺼비 형상’으로 알고 있었습니다. 월명동에 옮겨온 뒤에도 오랫동안 그같이 인식됐습니다."]}, {"p": ["그러던 2013년 가을, 월명동을 찾은 한 수석가가 바위를 측면에서 바라보다가 새로운 모습을 발견했습니다. 두꺼비 형상으로 알고 옮겨온 지 약 20년 만에, 바위의 근본 형상인 ‘코끼리 모습’을 새롭게 발견한 것입니다.", "이처럼 같은 대상도 어떤 생각과 관점으로 바라보느냐에 따라 다르게 보일 수 있습니다.", "고정된 인식을 비우고 올바른 각도에서 살펴보니 코끼리 바위라는 작품을 발견했듯, 자기 자신과 다른 사람도 마음의 눈을 뜨고 제 방향에서 보세요. 참 개성과 장점을 발견할 수 있을 것입니다."]}], "i18n": {"en": {"name": "The Elephant Rock", "alias": "", "body": [{"p": ["The elephant is the largest land animal and has long symbolized strength and majesty."]}, {"p": ["When this rock was first brought here, everyone, including the owner of the stone company, believed it resembled a toad. Even after it was moved to Wolmyeongdong, it continued to be recognized as a toad for a long time."]}, {"p": ["However, in the autumn of 2013, an ornamental rock expert visiting Wolmyeongdong discovered a new shape while viewing the rock from the side. Approximately 20 years after the rock had been brought here, believed to have the shape of a toad, its true form—that of an elephant—was finally discovered."]}, {"p": ["Likewise, even the same object can appear different depending on our thoughts and the perspective from which we view it."]}, {"p": ["Just as the Elephant Rock was discovered by letting go of fixed perceptions and viewing the rock from the right angle, open the eyes of your heart and look at yourself and others from the right perspective. You will discover your own and others' true individuality and strengths."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/kokkiri-bawi.en.v1.m4a", "audioDur": 93.5}, "ja": {"name": "象の岩", "alias": "", "body": [{"p": ["象は陸上で最も大きな動物で、古くから力と威厳を象徴してきました。"]}, {"p": ["この岩を初めて運んできた当時、石の会社の社長をはじめ、皆が「ヒキガエルの形象」だと思っていました。月明洞に移された後も、長い間そのように認識されていました。"]}, {"p": ["ところが2013年の秋、月明洞を訪れたある水石家が岩を側面から眺めていたところ、新たな姿を発見しました。ヒキガエルの形象だと思って運んできてから約20年後に、この岩の根本の形象である「象の姿」を新たに発見したのです。"]}, {"p": ["このように、同じ対象でも、どのような考えや観点から見るかによって、違って見えることがあります。"]}, {"p": ["固定された認識を手放し、正しい角度から見ることで「象の岩」という作品を発見したように、自分自身や他の人についても心の目を開き、正しい方向から見てみてください。本当の個性や長所を発見することができるでしょう。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/kokkiri-bawi.ja.v2.m4a", "audioDur": 107.0}, "zh": {"name": "大象石", "alias": "", "body": [{"p": ["大象是陸地上最大的動物，自古以來便象徵著力量與威嚴。"]}, {"p": ["這顆石頭最初被帶回來時，所有人包括石頭公司的老闆，都一致認為它具有蟾蜍的形像，所以搬來月明洞後，經過很長一段時間，大家還是這樣認知。"]}, {"p": ["然而，在2013年秋天，一位造訪月明洞的奇石家從側面觀察時，發現了這顆石頭的新面貌。它一直被認為是蟾蜍的形像，直到搬來約二十年後，才被發掘新的面貌、石頭的根本形像，也就是「大象」。"]}, {"p": ["也就是說，即使面對同一個對象，也會隨著觀看角度與想法的不同，而看得不一樣。"]}, {"p": ["如同在倒空固定認知、從正確的角度觀察後，就發現了「大象石」作品一般，請你們睜開內心的眼睛，從正確的方向觀察自己和他人，這樣將能發現真正的特質和優點。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/kokkiri-bawi.zh.v1.m4a", "audioDur": 110.4}}, "audio": "/sayeon/stones/audio/7-guide.mp3", "audioDur": 101.0}, {"no": 8, "id": "daedunsan-sansugyeongseok", "name": "대둔산 산수경석", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/daedunsan-sansugyeongseok-1.v3.webp", "w": 900, "h": 507}], "body": [{"p": ["대둔산 산수경석은 2026년 6월, 선생님이 말씀을 전파하기 시작한 날을 기리는 ‘알파절’을 맞아 월명동 자연성전에 들어온 대형 정원석입니다. 필리핀에서 형성된 수석으로, 가로 약 5m×너비 약 3m×높이 약 1.5m이며 무게는 약 22톤에 이릅니다."]}, {"p": ["이 수석의 가장 큰 특징은 크고 작은 봉우리들이 겹겹이 이어지며 웅장한 산세를 이루고 있다는 점입니다.", "돌 위에는 약 70여 개의 봉우리가 형성되어 있는데,", "예로부터 수려한 봉우리로 이름난 대둔산의 산세를 연상시킨다고 하여 ‘대둔산 산수경석’이라는 이름이 붙었습니다."]}, {"p": ["대둔산은 선생님이 오랫동안 기도와 수도 생활을 했던 장소입니다. 그만큼 의미가 깊은 이 산수경석을 하나님이 때에 맞춰 기적적으로 선물로 주신 것입니다."]}], "i18n": {"en": {"name": "Daedunsan Landscape Rock", "alias": "", "body": [{"p": ["The Daedunsan Landscape Rock is a massive garden rock that was brought to the Wolmyeongdong Natural Temple in June 2026 to mark Alpha Day, which commemorates the day Seonsaengnim began preaching the Word.", "This ornamental rock, formed in the Philippines, measures approximately 5 meters long, 3 meters wide, and 1.5 meters high, and weighs about 22 tons."]}, {"p": ["The most distinctive feature of this rock is its magnificent mountain landscape, formed by layers of overlapping peaks of various sizes. Approximately 70 peaks rise from its surface, resembling the mountain landscape of Mt. Daedun (Daedunsan), which has long been renowned for its beautiful peaks. This resemblance inspired the name \"Daedunsan Landscape Rock.\""]}, {"p": ["Mt. Daedun is a place where Seonsaengnim spent a long time in prayer and spiritual training. God miraculously gave this deeply meaningful Landscape Rock as a gift at just the right time."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/daedunsan-sansugyeongseok.en.v1.m4a", "audioDur": 86.8}, "ja": {"name": "テドゥン山山水景石", "alias": "", "body": [{"p": ["テドゥン山山水景石は、2026年6月、先生が御言葉を伝え始めた日を記念する「アルパ節」を迎え、月明洞自然聖殿に入ってきた大型の庭園石です。"]}, {"p": ["フィリピンで形成された水石で、横約5メートル×幅約3メートル×高さ約1.5メートル、重さは約22トンに達します。"]}, {"p": ["この水石の最大の特徴は、大小さまざまな峰々が幾重にも連なり、雄大な山容を成していることです。"]}, {"p": [{"t": "石の上には約70もの峰が形成されており、古くから秀麗な峰々で名高いテドゥン山の山容を思わせることから、「テドゥン山山水景石」という名前が付けられました。", "em": "「テドゥン山山水景石」"}]}, {"p": ["テドゥン山は、先生が長い間、祈りと修道生活をしていた場所です。それだけ意味深いこの山水景石を、神様が時に合わせて奇跡的に贈り物としてくださったのです。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/daedunsan-sansugyeongseok.ja.v2.m4a", "audioDur": 82.8}, "zh": {"name": "大芚山 山水景石", "alias": "", "body": [{"p": ["大芚山山水景石是大型庭園石，在2026年6月，配合老師開始傳揚話語的紀念日「阿拉法節」而來到月明洞自然聖殿。", "這是在菲律賓成形的奇石，長約5公尺、寬約3公尺、高約1.5公尺，重量約22噸。"]}, {"p": ["這奇石最大的特點是大大小小的山峰層層相疊，形成雄偉的山勢。", "這石頭上有約70多座的峰巒。", "由於它令人聯想到自古便以秀麗山峰聞名的大芚山山勢，因此命名為「大芚山山水景石」。"]}, {"p": ["大芚山是老師長年禱告、修道生活的地點。這深具意義的山水景石，是　神配合時機、奇蹟似地賜下的禮物。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/daedunsan-sansugyeongseok.zh.v1.m4a", "audioDur": 89.3}}, "audio": "/sayeon/stones/audio/106-guide.mp3", "audioDur": 91.1}, {"no": 9, "id": "bapsang-bawi", "name": "밥상바위", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/bapsang-bawi-1.v3.webp", "w": 900, "h": 600}], "body": [{"p": ["밥상바위는 ‘말씀의 밥상’이라는 의미를 지닌 바위입니다.단순한 조경석을 넘어 무대와 설교 단상으로 활용하고, 사람들에게 영혼의 양식을 전하는 ‘신령한 밥상’의 의미를 담아 이곳에 배치했습니다. 설교할 때 앉아서도 말씀을 전할 수 있도록 자연스럽게 자리가 형성되어 있는 것도 이 바위의 특징입니다."]}, {"p": ["무게 약 73톤, 너비 약 4m, 높이 1.5m가 넘는 대형 자연석입니다. 형태가 반듯하고 돌이 단단하며, 윗면이 넓어 사람이 올라가 앉거나 머물기에도 좋습니다."]}, {"p": [{"t": "이 바위는 본래 석막리 산에 묻혀 있었습니다. 선생님은 평소 알고 지내던 산 주인이 어려움을 겪을 때 도움을 주었고 이후 자신에게 오랜 추억이 담긴 이 바위를 선물로 받았습니다.  이러한 사연이 있어 “하늘 앞에서나 사람들에게나 잘해 주어야, 그로 인해 얻게 되는 것이 있다”는 교훈을 전하고 있습니다.", "em": "“하늘 앞에서나 사람들에게나 잘해 주어야, 그로 인해 얻게 되는 것이 있다”"}]}, {"p": ["밥상바위가 더욱 특별한 이유는 선생님의 어린 시절과 관련된 사연이 있기 때문입니다. 선생님은 10대와 20대 시절, 석막리 교회를 오가거나 쉬는 날이면 이 바위에 올라 주변 경치를 바라보곤 했습니다. 때로는 혼자, 때로는 동생이나 마을 사람들과 함께 이곳에서 시간을 보냈다고 합니다."]}, {"p": [{"t": "이 바위를 구할 당시 더 아름답고 값이 좋은 다른 돌도 있었지만, 선생님은 오랜 사연이 담긴 이 바위를 선택했습니다. 선생님은 지금도 이 바위를 보면 어린 시절의 추억이 떠오른다고 합니다.  “사연이 값이고, 사연이 기쁨이며 사랑이고 희망이다”.", "em": "“사연이 값이고, 사연이 기쁨이며 사랑이고 희망이다”"}]}], "i18n": {"en": {"name": "The Dining Table Rock", "alias": "", "body": [{"p": ["The Dining Table Rock carries the meaning of “the table of the Word.” More than just a landscaping rock, it was placed here to serve as a stage and preaching pulpit, embodying the meaning of a “spiritual table” that provides spiritual nourishment to people. Another distinctive feature of this rock is its naturally formed seat, which allows the Word to be preached while seated."]}, {"p": ["This massive natural rock weighs approximately 73 tons, measures about 4 meters wide, and stands over 1.5 meters high. It has a well-proportioned shape and a solid structure, with a broad, flat top that makes it suitable for people to sit or spend time on."]}, {"p": [{"t": "This rock was originally buried in a mountain in Seongmak-ri. When the owner of the mountain, whom Seonsaengnim had known for some time, was going through difficulties, Seonsaengnim helped him. Later, Seonsaengnim received this rock as a gift [from the owner], a rock that held many cherished memories for him. This story conveys the lesson: “When you treat both Heaven and people well, there are things you will gain as a result.”", "em": "“When you treat both Heaven and people well, there are things you will gain as a result.”"}]}, {"p": ["What makes the Dining Table Rock even more special is the story connected to Seonsaengnim’s younger years. In his teens and twenties, whenever he was traveling to and from the church in Seongmak-ri or had a day off, Seonsaengnim would climb onto this rock and look out over the surrounding scenery. Sometimes he spent time there alone, and at other times with his younger siblings or people from the village."]}, {"p": ["When acquiring this rock, there were other rocks that were more beautiful and valuable, but Seonsaengnim chose this one because of the many memories and stories associated with it. Seonsaengnim says that even today, whenever he looks at this rock, memories of his younger years come flooding back."]}, {"p": [{"q": "“The stories [behind things] are their value; stories are joy, love, and hope.”"}]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/bapsang-bawi.en.v1.m4a", "audioDur": 138.7}, "ja": {"name": "食卓岩", "alias": "", "body": [{"p": [{"t": "食卓岩は、「御言葉の食卓」という意味を持つ岩です。", "em": "「御言葉の食卓」"}]}, {"p": [{"t": "単なる造景石ではなく、舞台や説教壇として活用し、人々に魂の糧を伝える「霊的な食卓」という意味を込めて、この場所に配置されました。説教をするとき、座ったままでも御言葉を伝えられるよう、自然に座る場所が形成されていることも、この岩の特徴です。", "em": "「霊的な食卓」"}]}, {"p": ["重さ約73トン、幅約4メートル、高さ1.5メートルを超える大型の自然石です。形が整っていて石も硬く、上面が広いため、人が上に登って座ったり、そこに留まったりするのにも適しています。"]}, {"p": [{"t": "この岩は、もともと石幕里の山に埋まっていました。先生は、普段から親しくしていた山の持ち主が困難を経験していたときに助け、その後、ご自身にとって長年の思い出が込められたこの岩を贈り物として受け取りました。このような経緯があることから、「天の前でも人々に対してもよくしてこそ、それによって得られるものがある」という教訓を伝えています。", "em": "「天の前でも人々に対してもよくしてこそ、それによって得られるものがある」"}]}, {"p": ["食卓岩がさらに特別なのは、先生の幼い頃にまつわる経緯があるからです。先生は10代、20代の頃、石幕里教会に行き来するときや休みの日になると、この岩に登って周囲の景色を眺めたりしていました。時には一人で、時には弟や村の人々と一緒に、ここで時間を過ごしたといいます。"]}, {"p": ["この岩を手に入れた当時、ほかにも、より美しく価値の高い石がありましたが、先生は長年の経緯が刻まれたこの岩を選びました。先生は今でも、この岩を見ると幼い頃の思い出がよみがえるといいます。"]}, {"p": [{"q": "「経緯が価値であり、経緯が喜びであり、愛であり、希望だ。」"}]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/bapsang-bawi.ja.v2.m4a", "audioDur": 146.9}, "zh": {"name": "飯桌石", "alias": "", "body": [{"p": ["飯桌石具有「話語的飯桌」之意。", "這不僅僅是一塊簡單的造景石，而是作為舞臺和證道臺使用，傳遞給人們靈魂的糧食，意味著「神聖的飯桌」，因此被放置於此。這顆石頭的特點之一是，它自然地形成了能坐著證道的位置。"]}, {"p": ["飯桌石的重量約為73噸，寬度約4公尺，高度超過1.5公尺，是一塊大型自然石。石頭形狀端正且堅硬，而且頂部寬敞，適合人們上去坐或者停留。"]}, {"p": [{"t": "這顆石頭本來這顆石頭埋在石幕里山中。老師平時便與那座山的主人有所往來，曾經在山主遇到困難時給予幫助，最終得到這顆山主所贈、承載著悠久回憶的石頭。因為有這樣的故事，所以傳達的教誨是「在天面前和人面前都要做得好，才能因此得到回報」。", "em": "「在天面前和人面前都要做得好，才能因此得到回報」"}]}, {"p": ["飯桌石之所以更顯特別，是因為跟老師的童年有關。在老師十幾二十歲時，經常在往返石幕里教會的路上，或者在農閒時，爬到這顆石頭上眺望周圍的風景。有時是獨自一人，有時則是和弟弟或村裡的人一起在這裡度過時光。"]}, {"p": ["當初購買這顆石頭的時候，雖然還有其他更美麗、更有價值的石頭，但是老師選擇的是這顆充滿了悠久回憶與故事的石頭。老師說他到現在看見這顆石頭時，仍會想起童年的回憶。"]}, {"p": [{"q": "「故事就是價值，故事就是喜悅、愛與希望。」"}]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/bapsang-bawi.zh.v1.m4a", "audioDur": 156.1}}, "audio": "/sayeon/stones/audio/30-guide.mp3", "audioDur": 157.3}, {"no": 10, "id": "hanggongmoham-suseok", "name": "항공모함 수석", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/hanggongmoham-suseok-1.v3.webp", "w": 900, "h": 600}], "body": [{"p": ["‘항공모함 수석’은 길게 뻗은 윗면과 넓적한 몸체가 바다 위를 항해하는 거대한 항공모함을 연상시키는 자연석입니다. 항공모함은 흔히 ‘바다 위의 공항’이라 불리며, 해상에서 항공기가 이착륙할 수 있는 기지이자 다양한 장비와 전력을 갖춘 역할을 합니다."]}, {"p": ["이 항공모함 수석은 ‘신앙의 무장’을 상징합니다. 성경 에베소서 6장에서 사도 바울이 당시의 투구와 검 등 전쟁 장비를 신앙의 무장에 비유했습니다. 과학기술이 발달한 오늘날, 하나님은 항공모함과 같은 현대식 무기에 비유해 말씀하고 계십니다."]}, {"p": ["항공모함 수석을 비롯한 무기 형상 수석 시리즈는보이지 않는 영적 전쟁의 때에 우리도 군인이 전투를 준비하듯 신앙을 굳건히 무장해야 함을 알려줍니다."]}, {"p": ["우리가 갖춰야 할 신앙의 무기는 네 가지입니다.", "첫째는 기도, 둘째는 말씀, 셋째는 사명, 넷째는 조직입니다."]}, {"p": ["기도와 말씀으로 마음과 정신을 굳건히 하고, 맡겨진 사명을 실천하며, 서로 의논하고 하나 되어 담대하게 나아가는 것. 이것이 항공모함 수석을 통해 전하고자 하는 핵심적인 신앙의 교훈입니다."]}], "i18n": {"en": {"name": "The Aircraft Carrier Rock", "alias": "", "body": [{"p": ["The Aircraft Carrier Rock is a natural rock whose long, extended top and broad body resemble a massive aircraft carrier sailing across the sea. An aircraft carrier is often called “an airport at sea.” It serves as a base where aircraft can take off and land at sea and is equipped with various types of equipment and military capabilities."]}, {"p": ["The Aircraft Carrier Rock symbolizes being “armed in faith.” In Ephesians 6, the Apostle Paul compared the military equipment of his time, such as a helmet and sword, to being armed in faith. Today, in this age of advanced science and technology, God speaks through comparisons to modern weapons such as aircraft carriers."]}, {"p": ["The series of weapon-shaped ornamental rocks, including the Aircraft Carrier Rock, teaches us that in times of invisible spiritual warfare, we too must firmly arm ourselves in faith, just as soldiers prepare for battle."]}, {"p": ["There are four weapons of faith with which we must equip ourselves: first, prayer; second, the Word; third, mission; and fourth, organization."]}, {"p": ["Strengthening our hearts and minds through prayer and the Word, carrying out the missions entrusted to us, and moving forward boldly by consulting with one another and becoming one—this is the central lesson of faith conveyed through the Aircraft Carrier Rock."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/hanggongmoham-suseok.en.v1.m4a", "audioDur": 117.0}, "ja": {"name": "航空母艦の水石", "alias": "", "body": [{"p": ["「航空母艦の水石」は、長く伸びた上面と幅広い胴体が、海の上を航海する巨大な航空母艦を思わせる自然石です。航空母艦はよく「海上の空港」と呼ばれ、海上で航空機が離着陸できる基地であり、さまざまな装備と戦力を備えています。"]}, {"p": ["この航空母艦の水石は、「信仰の武装」を象徴しています。"]}, {"p": ["聖書のエペソ人への手紙6章で、使徒パウロは当時の兜や剣などの戦争装備を信仰の武装にたとえました。科学技術が発達した今日、神様は航空母艦のような現代の武器にたとえて御言葉を伝えられます。"]}, {"p": ["航空母艦の水石をはじめとする武器の形象をした水石シリーズは、目に見えない霊的な戦争の時に、私たちも軍人が戦闘に備えるように、信仰を強固に武装しなければならないことを教えてくれます。"]}, {"p": ["私たちが備えるべき信仰の武器は四つあります。"]}, {"p": ["第一は祈り、第二は御言葉、第三は使命、第四は組織です。"]}, {"p": ["祈りと御言葉で心と精神を強固にし、任された使命を実践し、互いに話し合い、一つになって大胆に進んでいくこと。これが航空母艦の水石を通して伝えようとしている、核心的な信仰の教訓です。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/hanggongmoham-suseok.ja.v2.m4a", "audioDur": 127.2}, "zh": {"name": "航空母艦石", "alias": "", "body": [{"p": ["「航空母艦奇石」是一顆自然石，其向前延伸的頂部與扁平的形像，令人聯想到航行在海上的巨大航空母艦。航空母艦常被稱為「海上機場」，是大海上可供飛機起降的基地，具備各種裝備與戰力，發揮重要的作用。"]}, {"p": ["這顆航空母艦奇石，象徵「信仰的武裝」。", "在聖經以弗所書6章中，使徒保羅提到了信仰的武裝，以頭盔、劍等當時的戰爭裝備來比喻。而在科學技術發達的今日，　神便以航空母艦等現代化武器作為比喻來傳達話語。"]}, {"p": ["以航空母艦奇石為首的武器形像奇石系列，是要告訴我們，在看不見的屬靈戰爭中，我們也應當如同軍人準備戰鬥那般，堅定地武裝信仰。"]}, {"p": ["我們該具備的信仰武器有四樣。", "第一是禱告，第二是話語，第三是使命，第四是組織。"]}, {"p": ["要以禱告與話語堅定內心和精神，實踐被交付的使命，彼此討論後合一，大膽地前進。這就是要透過這顆航空母艦奇石傳達的核心信仰教誨。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/hanggongmoham-suseok.zh.v1.m4a", "audioDur": 138.3}}, "audio": "/sayeon/stones/audio/65-guide.mp3", "audioDur": 119.0}, {"no": 11, "id": "jeonpokgi-suseok", "name": "전폭기 수석", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/jeonpokgi-suseok-1.v3.webp", "w": 900, "h": 600}, {"src": "https://grand-pasca-8d267f.netlify.app/images/jeonpokgi-suseok-2.v3.webp", "w": 900, "h": 513}], "body": [{"p": ["‘전투기 형상석’은 현대식 전투기가 날렵하게 뻗어 나가는 모습을 닮은 자연석입니다. 마치 조각가가 형태를 잡아 놓은 듯 전투기의 윤곽이 선명하게 드러나는 것이 특징입니다."]}, {"p": ["이 전투기 형상석과 함께 미사일 폭탄을 닮은 자연석도 발견되었습니다. 선생님은 각각의 형상이 더욱 분명하게 드러나도록 항공모함, 전투기, 미사일 형상석을 하나의 장면처럼 배치하도록 구상했습니다. 특히 전투기 밑에 미사일 모양의 돌을 놓아 전체 구성이 자연스럽게 연결되도록 했습니다."]}, {"p": ["이 과정에서 선생님은 특히 제자들에게 ‘연출’의 중요성​을 강조했습니다."]}, {"p": [{"q": "“연출은 단장이다. 방향이다. 무대요, 차림새요, 증거다.”"}]}, {"p": ["자연석은 바라보는 방향과 놓이는 위치에 따라 사람이나 동물, 사물 등 서로 다른 형상으로 보일 수 있습니다. 따라서 수석은 돌 자체의 형태뿐 아니라 어떤 방향과 구도로 배치했는가도 중요한 감상 요소입니다."]}, {"p": ["전투기 형상석 역시 이러한 연출을 통해 자연이 만든 형상과 작품의 특징이 더욱 선명하게 드러납니다."]}], "i18n": {"en": {"name": "The Fighter-Bomber Rock", "alias": "", "body": [{"p": ["“The Fighter-Jet-Shaped Rock” is a natural rock resembling the sleek, streamlined form of a modern fighter jet in flight. Its distinctive feature is the clearly defined outline of a fighter jet, as though it had been shaped by a sculptor."]}, {"p": ["Along with this fighter-jet-shaped rock, a natural rock resembling a missile was also discovered. Seonsaengnim envisioned arranging the aircraft carrier, fighter jet, and missile-shaped rocks together as a single scene so that each form would stand out more clearly. In particular, he placed the missile-shaped rock beneath the fighter jet so that the entire composition would flow together naturally."]}, {"p": ["During this process, Seonsaengnim particularly emphasized to his disciples the importance of “presentation.”"]}, {"p": [{"q": "“Presentation is adornment. It is direction, a stage, appearance, and testimony.”"}]}, {"p": ["Depending on the direction from which they are viewed and how they are positioned, natural rocks can appear to take on various images, such as people, animals, or objects. Therefore, when appreciating ornamental rocks, not only the shape of the rock itself but also the direction and composition in which it is arranged are important."]}, {"p": ["Through such presentation, the Fighter Jet Rock more clearly reveals both the image formed by nature and the distinctive features of the work."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/jeonpokgi-suseok.en.v1.m4a", "audioDur": 91.6}, "ja": {"name": "戦爆機の水石", "alias": "", "body": [{"p": ["「戦爆機の水石」は、現代の戦闘機が鋭く伸びて飛んでいく姿に似た自然石です。まるで彫刻家が形を整えたかのように、戦闘機の輪郭がはっきりと現れていることが特徴です。"]}, {"p": ["この戦爆機の水石と共に、ミサイル爆弾に似た自然石も発見されました。先生は、それぞれの形象がより明確に現れるよう、航空母艦、戦闘機、ミサイルの形象石を一つの場面のように配置することを構想しました。特に戦闘機の下にミサイルの形をした石を置き、全体の構成が自然につながるようにしました。"]}, {"p": ["この過程で先生は、特に弟子たちに「演出」の重要性を強調しました。"]}, {"p": [{"q": "「演出は装いだ。方向だ。舞台であり、身なりであり、証だ。」"}]}, {"p": ["自然石は、見る方向や置かれる位置によって、人や動物、物など、さまざまな形象に見えることがあります。そのため、水石は石そのものの形だけでなく、どのような方向や構図で配置されているかも重要な鑑賞要素です。"]}, {"p": ["戦爆機の水石もまた、このような演出によって、自然がつくり出した形象と作品の特徴がより鮮明に現れています。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/jeonpokgi-suseok.ja.v2.m4a", "audioDur": 96.8}, "zh": {"name": "戰鬥轟炸機石", "alias": "", "body": [{"p": ["「戰鬥機形像石」是一顆自然石，相似於現代戰鬥機俐落地向前飛馳的形像，其特色是具有清楚的戰鬥機輪廓，彷彿雕刻家特意雕刻而成。"]}, {"p": ["在與這顆戰鬥機形像石一起發現的其他石頭中，還有一顆酷似導彈的石頭。老師想到了一種配置方式，讓航空母艦、戰鬥機與導彈形像石構成一幅畫面，藉此使各自的形像看起來更加鮮明；而且特地把導彈模樣的石頭放到戰鬥機奇石的底下，讓整體自然地結合起來。"]}, {"p": ["在這過程中，老師特別對弟子們強調了「呈現」的重要性。"]}, {"p": [{"q": "「呈現指的是裝飾、是方向、是舞台、是打扮、是見證。」"}]}, {"p": ["自然石隨著觀看方向及擺放位置的不同，能看出人、動物或者物品等不同的形像。因此，觀賞奇石的時候，除了石頭本身的模樣之外，它是以什麼方向擺放、讓人從哪個方向觀看，也是很重要的觀賞要素。"]}, {"p": ["戰鬥機形像石也透過這樣的呈現，更清楚地展現出大自然創造的形像與作品特徵。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/jeonpokgi-suseok.zh.v1.m4a", "audioDur": 118.4}}, "audio": "/sayeon/stones/audio/66-guide.mp3", "audioDur": 108.6}, {"no": 12, "id": "sansugyeongseok", "name": "산수경석", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/sansugyeongseok-1.v3.webp", "w": 900, "h": 600}], "body": [{"p": ["‘산수경석’은 산과 골짜기, 봉우리와 폭포 등 자연의 풍경이 축소되어 한 폭의 산수화를 이루는 듯한 수석을 말합니다. 좌측 봉우리가 높고 우측 봉우리가 낮게 이어지는 등 자연스러운 산세를 갖춘 돌은 드물어 귀한 수석으로 평가됩니다."]}, {"p": ["산수경석을 찾게 된 계기가 있습니다. 어느 날 월명동을 방문한 수석 전문가들이 큰 돌이 많은데 산수경석이 없다며 아쉬움을 표현했습니다. 선생님은 처음에는 이 말을 듣고 마음이 상하기도 했지만, 오히려 이를 계기로 월명동에 어울리는 산수경석을 찾아보기로 했습니다.", "2021년 마지막 주간, 선생님은 성령님이 주실 것이 있다는 말씀을 듣고 잔디밭 위쪽으로 올라가던 중 ‘있는 데서 찾으라’는 감동을 받고 주변을 살펴보았습니다. 낙타바위 오른쪽에서 두 봉우리가 솟아 있는 바위를 발견했습니다. 이 바위는 오랫동안 길바닥에 묻혀 사람들이 밟고 다니던 돌이었습니다."]}, {"p": ["주변의 영산홍과 흙을 걷어내며 약 4~5일 동안 작업하자, 높이 1m 이상, 길이 약 12m에 이르는 웅장한 산수경석의 모습이 드러났습니다.", "특히 잔디밭 쪽에서 바라보면 산수경석과 뒤편의 낙타바위가 자연스럽게 겹쳐져 더욱 웅장한 풍경을 이룹니다."]}, {"p": ["이 산수경석뿐 아니라 월명동의 앞산에서 동그래산으로 이어지는 지형도 거대한 산수경석 형상을 하고 있는 작품입니다."]}, {"p": ["한때는 천대받고 불편하게만 여겨졌던 돌도 때가 되자 산수경석이라는 대걸작품이 되었습니다. 이처럼 하나님의 때가 오면 자신도, 타인도 그 귀한 가치가 드러납니다."]}], "i18n": {"en": {"name": "The Landscape Rock", "alias": "", "body": [{"p": ["A “Landscape Rock” is an ornamental rock in which natural scenery—such as mountains, valleys, peaks, and waterfalls—appears in miniature, as though forming a landscape painting. Rocks with a natural mountain landscape, such as a high peak on the left flowing into lower peaks on the right, are rare and are therefore considered especially valuable ornamental rocks."]}, {"p": ["There is a story behind how this Landscape Rock came to be discovered. One day, ornamental rock experts visiting Wolmyeongdong expressed their disappointment that although there were many large rocks, there were no landscape rocks. At first, Seonsaengnim felt hurt by their comment. However, he decided to take it as an opportunity to search for a landscape rock that would complement Wolmyeongdong."]}, {"p": ["During the final week of 2021, Seonsaengnim heard the Holy Spirit tell him that She had something to give him. As he was walking up toward the area above the lawn, he felt inspired to “find it among what you already have” and began looking around."]}, {"p": ["To the right of the Camel Rocks, he discovered a rock with two peaks rising from it. This rock had been buried in the path for a long time, with people walking over it."]}, {"p": ["After removing the azaleas and soil around it over the course of about four to five days, a magnificent landscape rock measuring over one meter high and approximately 12 meters long was revealed.", "In particular, when viewed from the lawn, the Landscape Rock and the Camel Rocks behind it naturally overlap, creating an even more magnificent landscape."]}, {"p": ["Not only this Landscape Rock, but also the terrain extending from the Front Hill in Wolmyeongdong to the Round Hill is a work that takes the form of one enormous landscape rock."]}, {"p": ["Even a rock that was once disregarded and considered nothing but an inconvenience became a great masterpiece—a landscape rock—when its time came. Likewise, when God’s time comes, the precious value within both ourselves and others is revealed."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/sansugyeongseok.en.v1.m4a", "audioDur": 165.3}, "ja": {"name": "山水景石", "alias": "", "body": [{"p": ["「山水景石」とは、山や谷、峰や滝などの自然の風景が縮小され、一幅の山水画を成しているかのような水石のことをいいます。左側の峰が高く、右側の峰が低く連なるなど、自然な山容を備えた石は珍しく、貴重な水石として評価されています。"]}, {"p": ["山水景石を探すことになったきっかけがあります。ある日、月明洞を訪れた水石の専門家たちが、大きな石は多いのに山水景石がないと残念がりました。先生は初め、この言葉を聞いて心を痛めましたが、むしろこれをきっかけに、月明洞にふさわしい山水景石を探してみることにしました。"]}, {"p": [{"t": "2021年最後の週、先生は聖霊様から「与えるものがある」という御言葉を聞き、芝生広場の上の方へ登っていたところ、「あるところから探しなさい」という感動を受け、周囲を見渡しました。", "em": "「与えるものがある」"}]}, {"p": ["ラクダ岩の右側に、二つの峰がそびえている岩を発見しました。この岩は長い間、道に埋もれ、人々に踏まれていた石でした。"]}, {"p": ["周囲のサツキや土を取り除きながら約4～5日間作業すると、高さ1メートル以上、長さ約12メートルに達する雄大な山水景石の姿が現れました。"]}, {"p": ["特に芝生の方から眺めると、山水景石と後方のラクダ岩が自然に重なり、より雄大な風景をつくり出します。"]}, {"p": ["この山水景石だけでなく、月明洞の前山からトングレ山へと続く地形も、巨大な山水景石の形象をしている作品です。"]}, {"p": ["かつては軽んじられ、不便なものとしか思われていなかった石も、時が来ると山水景石という大傑作品になりました。このように神様の時が来れば、自分自身も、他の人も、その貴重な価値が現れます。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/sansugyeongseok.ja.v2.m4a", "audioDur": 169.8}, "zh": {"name": "山水景石", "alias": "", "body": [{"p": ["山水景石指的是山嶺、谷地、峰巒、瀑布等自然風景如同一幅山水畫般縮小呈現在石頭上的奇石，左峰高、右峰低，山勢自然綿延的石頭極為罕見，因此被評價為珍貴奇石。"]}, {"p": [{"t": "找到這顆山水景石的契機如下。某天，幾位奇石專家來到月明洞，他們說：「這裡有很多大石頭，卻沒有山水景石，真可惜！」老師起初聽了有些難過，但反而因此決心尋找適合月明洞的山水景石。", "em": "「這裡有很多大石頭，卻沒有山水景石，真可惜！」"}]}, {"p": [{"t": "2021年最後一週，老師聽見聖靈說「我有東西要給你」。當老師往草坪上方走去時，得到感動：「要在已有的地方尋找。」於是，老師環顧四周。", "em": "「我有東西要給你」"}]}, {"p": ["就在駱駝石右側，看見一顆石頭上面竟有兩座峰巒聳立。那是一顆長年埋在路邊、被人踩踏的岩石。"]}, {"p": ["在連續工作四、五天，清理周圍的映山紅與泥土後，一顆高出1公尺、長約12公尺的雄壯山水景石出現在眼前。", "尤其從草坪方向望去，這顆山水景石與後方的駱駝石自然重疊，形成更加壯麗的景觀。"]}, {"p": ["不僅這顆山水景石，月明洞前山到圓山之間的地形，也是一件構成巨大山水景石形像的作品。"]}, {"p": ["曾經被踩踏、令人感到不便的石頭，時機一到，便成為了大傑作「山水景石」；同樣地，在　神的時機來臨時，自己與他人的寶貴價值將會顯明。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/sansugyeongseok.zh.v1.m4a", "audioDur": 171.3}}, "audio": "/sayeon/stones/audio/4-guide.mp3", "audioDur": 163.6}, {"no": 13, "id": "nakta-bawi", "name": "낙타바위", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/nakta-bawi-1.v3.webp", "w": 900, "h": 675}], "body": [{"p": ["두 마리 거대한 낙타 형상을 하고 있는 이 바위는 땅속에 묻혀 있던 바위를 오랜 시간 파내면서 발견한 거대한 형상석입니다."]}, {"p": ["월명동 자연성전을 조성하던 당시, 선생님은 수백톤의 바위를 달라고, 무에서 유를 창조하는 전설적인 작품을 달라고 하나님께 기도했습니다. 그러던 중 과거 밭을 갈 때 걸리곤 했던 작은 돌을 파보라는 감동을 받고 제자들과 함께 주변의 흙을 파내기 시작했습니다."]}, {"p": ["처음에 바위는 사과 상자만 한 크기로 보였지만, 계속해서 흙을 걷어내자 점차 큰 규모가 드러났습니다. 5년에 걸쳐 조심스럽게 파내자 긴 목과 몸체가 나타나면서 마침내 500톤에 이르는 웅장한 암낙타 형상이 나타났습니다.이후 더 파보니 그 옆에서도 또 하나의 수낙타 형상이 발견됐습니다. 암낙타와 수낙타를 합친 규모는 무려 1,200톤에 이릅니다."]}, {"p": ["낙타바위에는 성경적 의미가 담겨 있습니다. 성경에서 동방박사들은 별을 따라 예수님이 태어나신 곳까지 낙타를 타고 찾아가 황금과 유향, 몰약을 예물로 드렸습니다.또한 월명동 자연성전은 전체 지형이 5개의 골짜기로 이루어진 ‘별 모양’입니다. 월명동 안에도 별 모양 봉우리인 전망대가 있습니다. 월명동을 공중에서 보면 낙타바위가 별 모양 전망대를 향하고 있어 더욱 의미가 깊습니다.  낙타바위는 큰 인물이 태어났음을 상징합니다. 또한 꾸준히 끝까지 사막을 걸어 기쁜 소식을 전해듣고 가는 우리의 모습을 상징합니다.", "처음에는 작게 드러난 돌에 불과했지만 끝까지 파내자 거대한 자연 작품의 본연의 모습을 드러낸 낙타바위. 이처럼 자신과 다른 사람 안에 아직 드러나지 않은 가능성과 보화를 발견해 보시기 바랍니다."]}], "i18n": {"en": {"name": "The Camel Rocks", "alias": "", "body": [{"p": ["These rocks, which take the form of two enormous camels, are massive image rocks that were discovered by excavating rocks buried underground over a long period of time."]}, {"p": ["While developing the Wolmyeongdong Natural Temple, Seonsaengnim prayed to God to give him a rock weighing hundreds of tons—a legendary work that would create something out of nothing. Then, he felt inspired to dig around a small rock that used to get in the way when plowing the field, so he and his disciples began removing the soil around it."]}, {"p": ["At first, only a portion of the rock about the size of an apple box was visible. However, as they continued removing the soil, its enormous size gradually came to light. After carefully excavating it over a period of five years, a long neck and body emerged, finally revealing the magnificent form of a female camel weighing as much as 500 tons.", "As they continued digging, another rock in the form of a male camel was discovered beside it. Together, the female and male camel rocks weigh an astonishing 1,200 tons."]}, {"p": ["The Camel Rocks carry biblical significance. In the Bible, the Magi followed the star to the place where Jesus was born, riding camels, and presented gifts of gold, frankincense, and myrrh."]}, {"p": ["The overall topography of the Wolmyeongdong Natural Temple is also star-shaped, formed by five valleys. Within Wolmyeongdong, there is also a star-shaped peak called Jeonmangdae (Observatory Hill). When Wolmyeongdong is viewed from above, the Camel Rocks can be seen facing the star-shaped Jeonmangdae, giving them even greater significance."]}, {"p": ["The Camel Rocks symbolize the birth of a great figure. They also symbolize us steadily journeying through the desert to the very end to hear the joyful news."]}, {"p": ["At first, only a small part of the rock was visible, but after it was excavated to the very end, the Camel Rocks revealed their true form as a magnificent work of nature. Likewise, we encourage you to discover the potential and treasures within yourself and others that have yet to be revealed."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/nakta-bawi.en.v1.m4a", "audioDur": 166.0}, "ja": {"name": "ラクダ岩", "alias": "", "body": [{"p": ["二頭の巨大なラクダの形象をしているこの岩は、地中に埋まっていた岩を長い時間をかけて掘り出す中で発見された巨大な形象石です。"]}, {"p": ["月明洞自然聖殿をつくっていた当時、先生は数百トンの岩をください、無から有を創造する伝説的な作品をくださいと神様に祈りました。そのような中、以前、畑を耕すときに引っかかっていた小さな石を掘ってみなさいという感動を受け、弟子たちと一緒に周囲の土を掘り始めました。"]}, {"p": ["初め、岩はリンゴ箱ほどの大きさに見えましたが、土を取り除き続けると、次第にその大きな姿が現れました。5年にわたって慎重に掘り出すと、長い首と胴体が現れ、ついには500トンに達する雄大な雌ラクダの形象が姿を現しました。"]}, {"p": ["その後、さらに掘ってみると、その隣からもう一頭の雄ラクダの形象も発見されました。雌ラクダと雄ラクダを合わせた規模は、実に1,200トンに達します。"]}, {"p": ["ラクダ岩には、聖書的な意味が込められています。聖書で東方の博士たちは、星に従ってイエス様がお生まれになった場所までラクダに乗って訪ねて行き、黄金、乳香、没薬を贈り物として捧げました。"]}, {"p": ["また、月明洞自然聖殿は、全体の地形が五つの谷からなる「星形」です。月明洞の中にも、星形の峰である展望台があります。月明洞を上空から見ると、ラクダ岩が星形の展望台の方を向いており、さらに深い意味を持っています。"]}, {"p": ["ラクダ岩は、大きな人物が誕生したことを象徴しています。また、砂漠を最後まで着実に歩き、喜ばしい知らせを聞いて進んでいく私たちの姿を象徴しています。"]}, {"p": ["初めは小さく姿を現した石にすぎませんでしたが、最後まで掘り出すと、巨大な自然の作品として本来の姿を現したラクダ岩。このように、自分自身や他の人の中に、まだ現れていない可能性と宝を発見してみてください。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/nakta-bawi.ja.v2.m4a", "audioDur": 170.9}, "zh": {"name": "駱駝石", "alias": "", "body": [{"p": ["具有兩隻巨大駱駝形像的這岩石，原本被埋在地裡，是後來經過長時間挖掘而發現的巨大形像石。"]}, {"p": ["在建設月明洞自然聖殿的時候，老師向　神禱告，求　神賜下從無中創造出有的傳說性作品、重達數百噸的石頭。直到有一天，老師得到感動，要挖出一顆以前在耕地時經常會卡到的小石頭，便開始與弟子們一起挖出那石頭附近的土。"]}, {"p": ["這岩石一開始看起來只有蘋果箱般的大小，但隨著不斷挖土，石頭的規模才逐漸越來越大。小心翼翼地挖掘五年後，長長的脖子和身體終於顯現出來，最終出現了500噸重的母駱駝形像，非常雄壯。", "後來繼續挖土，在旁邊又發現了另一隻公駱駝的形像。母駱駝和公駱駝的重量加起來足足有1,200噸。"]}, {"p": ["駱駝石蘊含著聖經的意義。聖經中，東方博士跟隨星星騎著駱駝前往耶穌誕生之地，將黃金、乳香和沒藥獻給耶穌。"]}, {"p": ["此外，月明洞自然聖殿整體地形是由五個山谷構成的「星形」，而月明洞境內也有一個星形山峰的展望臺。從空中俯瞰月明洞，能看見駱駝石正朝著這星形的展望臺，因此意義更加深遠。"]}, {"p": ["駱駝石象徵偉大人物的誕生；此外，也象徵著我們持之以恆地橫越沙漠走到底，聽見喜悅的消息後，再繼續前行的樣子。"]}, {"p": ["駱駝石起初只露出一小部分，但挖到底後，原本的巨大自然作品就顯現出來了。就像這樣，願大家在看自己、看別人時，也試著發掘其中尚未顯現的可能性與寶藏。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/nakta-bawi.zh.v1.m4a", "audioDur": 168.4}}, "audio": "/sayeon/stones/audio/17-guide.mp3", "audioDur": 177.8}, {"no": 14, "id": "wolmyeongseok", "name": "월명석", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/wolmyeongseok-1.v3.webp", "w": 900, "h": 598}], "body": [{"p": ["이 수석은 2026년 5월 돌축제 기간 중 새로 들어온 정원석입니다. 아름다운 정원석의 산지로 알려진 인도네시아에서 발굴됐습니다. 선생님은 이 수석을 주신 성령님께 간구하며  20가지 좋은 점을 찾아냈고, 이는 수석의 가치를 더욱 빛나게 했습니다.", "먼저 이 수석의 최고 좋은 점은 백두산 천지못의 형상과 모양을 갖춘 것입니다. 이러한 형태의 자연석은 쉽게 찾아보기 어려워 더욱 귀한 수석으로 평가됩니다. 이 형상은 월명동 자연성전의 지형 형상 중 백두산 천지 형상과 닮았습니다. 월명동에 난 4개의 길을 비롯해 별봉정과 동그래산, 횟골 등의 지형까지 수석 위에 구현되어 있습니다. 그렇기에 ‘월명석’이란 이름으로 명명하게 되었습니다.또한 월명석은 속이 타원형으로 파여있어 신비합니다. 수만년동안 물이 엄청나게 빠른 속도로 휘몰아치며 지금의 모양으로 깎인 것입니다.", "월명석에는 오랜 세월 물에 깎이며 자연적으로 형성된 7개의 둥글둥글한 봉우리와 8곳의 물이 고이는 웅덩이가 있습니다. 그중 가장 큰 웅덩이는 100L 이상의 물을 담을 수 있고 성인 3명이 충분히 들어갈 만큼 깊습니다. 내부에는 산수경석의 형상까지 있어 신비로움을 더합니다."]}, {"p": ["뿐만 아니라 월명석에는 사람의 형상 2가지도 숨어 있습니다. 그 형상을 직접 찾아보세요.", "여기에 가로 3.5m × 세로 1.5m × 폭 2.5m, 무게 14.8톤에 이르는 거대한 크기와 균형 잡힌 비율, 뛰어난 강도를 갖추고 있습니다. 또한 수만 년 동안 물에 깎여 다듬어진 매끈하고 부드러운 표면도 특징입니다. 월명동 자연성전을 방문한 수석 전문가들도 감탄하고 있습니다."]}, {"p": ["그렇다면 월명석은 어떻게 월명동 자연성전에 오게 되었을까요?"]}, {"p": ["선생님은 오래 전부터 월명동의 지형을 닮은 돌을 구하고자 기도해오셨습니다. 하나님의 뜻이 어린 월명동 자연성전을 축소판처럼 한 눈에 보면서 가르치기 위함이었습니다. 그러던 중 선생님은 기도 중 혼으로 본 수석의 모습을 그림으로 그려 제자인 수석가에게 보여주며, 이와 같은 수석을 찾아보라고 하셨습니다. 수석가는 그림을 보는 순간 4년 전 경주에서 보았던 한 수석 작품이 떠올랐습니다."]}, {"p": ["수석이 정확히 어디에 있는지도 모른 채 경주로 달려간 수석가는 성령님의 인도하심으로 불과 20분 만에 그 수석을 발견했습니다. 이후 돌 주인의 마음이 감동되어 이례적인 가격으로 수석을 구할 수 있었고, 마침내 월명동 자연성전으로 옮겨오게 되었습니다."]}, {"p": ["이처럼 자신의 때가 아니라 하나님의 때에 맞춰 행할 때, 하는 일이 잘된다는 교훈도 월명석의 사연 속에 담겨 있습니다."]}], "i18n": {"en": {"name": "Wolmyeong Rock", "alias": "", "body": [{"p": ["This ornamental rock is a new garden rock that was brought to Wolmyeongdong during the Rock Festival in May 2026. It was excavated in Indonesia, a region known for its beautiful garden rocks. While praying earnestly to the Holy Spirit, who gave him this ornamental rock, Seonsaengnim discovered 20 outstanding features, further highlighting the rock’s value."]}, {"p": ["First and foremost, the greatest feature of this ornamental rock is that it has the form and shape of Cheonji Lake on Mt. Baekdu. Natural rocks with such a formation are difficult to find, making this an especially valuable ornamental rock.", "This formation also resembles the Mt. Baekdu Cheonji formation found in the topography of the Wolmyeongdong Natural Temple. The four roads running through Wolmyeongdong, along with geographical features such as the Star Peak Gazebo, the Round Hill, and Hwetgol, are even represented on the rock. For this reason, it was named “Wolmyeong Rock.”"]}, {"p": ["Another mysterious feature of the Wolmyeong Rock is its hollow, oval-shaped interior. Over tens of thousands of years, water swirled through it at tremendous speed, carving the rock into its present shape."]}, {"p": ["The Wolmyeong Rock has seven rounded peaks and eight pools where water collects, all naturally formed through water erosion over a long period of time. The largest pool can hold more than 100 liters of water and is deep enough to accommodate three adults. Inside, there is even a formation resembling a landscape rock, adding to its mysterious qualities."]}, {"p": ["In addition, two human images are hidden within the Wolmyeong Rock. See if you can find them yourself."]}, {"p": ["The rock is also remarkable for its massive size, balanced proportions, and exceptional strength. It measures 3.5 meters long, 1.5 meters high, and 2.5 meters wide, and weighs 14.8 tons. Another distinctive feature is its smooth, gently polished surface, shaped by water over tens of thousands of years. Ornamental rock experts who have visited the Wolmyeongdong Natural Temple have also expressed their admiration for it."]}, {"p": ["So, how did the Wolmyeong Rock come to the Wolmyeongdong Natural Temple?"]}, {"p": ["For a long time, Seonsaengnim had been praying to find a rock that resembled the topography of Wolmyeongdong. His purpose was to use it as a miniature representation of the Wolmyeongdong Natural Temple, which embodies God’s will, so that people could see it at a glance and learn from it."]}, {"p": ["Then, while praying, Seonsaengnim saw an ornamental rock with his soul. He drew what he had seen and showed the drawing to one of his disciples, an ornamental rock expert, telling him to look for a rock like it. The moment the expert saw the drawing, he remembered an ornamental rock he had seen in Gyeongju four years earlier."]}, {"p": ["Without even knowing exactly where the rock was, the expert rushed to Gyeongju. With the guidance of the Holy Spirit, he found the rock in just 20 minutes. Later, the rock owner’s heart was moved, allowing them to acquire the rock at an exceptionally favorable price, and it was finally brought to the Wolmyeongdong Natural Temple."]}, {"p": ["The story of the Wolmyeong Rock also teaches us that things go well when we act according to God’s timing rather than our own."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/wolmyeongseok.en.v1.m4a", "audioDur": 322.5}, "ja": {"name": "月明石", "alias": "", "body": [{"p": ["この水石は、2026年5月の岩の祝祭の期間中に新たに入ってきた庭園石です。美しい庭園石の産地として知られるインドネシアで発掘されました。先生は、この水石を与えてくださった聖霊様に祈り求めながら、20の良い点を見つけ出し、それによって水石の価値がさらに輝くようになりました。"]}, {"p": ["まず、この水石の最も優れた点は、白頭山の天池の形象と形を備えていることです。このような形の自然石は簡単には見つからないため、より貴重な水石として評価されています。"]}, {"p": ["この形象は、月明洞自然聖殿の地形のうち、白頭山の天池の形象と似ています。月明洞にある四つの道をはじめ、ピョルボン亭、トングレ山、フェッコルなどの地形まで、水石の上に表現されています。そのため、「月明石」と名付けられました。"]}, {"p": ["また、月明石は内部が楕円形にくぼんでおり、神秘的です。数万年もの間、水が非常に速い勢いで渦巻きながら流れ、現在の形に削られたものです。"]}, {"p": ["月明石には、長い歳月にわたって水に削られ、自然に形成された七つの丸みを帯びた峰と、水がたまる八つのくぼみがあります。その中で最も大きなくぼみには100リットル以上の水をためることができ、大人3人が十分に入れるほどの深さがあります。内部には山水景石の形象まであり、さらに神秘的な趣を加えています。"]}, {"p": ["それだけでなく、月明石には二つの人の形象も隠されています。その形象をぜひ直接探してみてください。"]}, {"p": ["さらに、横3.5メートル×縦1.5メートル×幅2.5メートル、重さ14.8トンに達する巨大な大きさと均整の取れた比率、優れた強度を備えています。また、数万年にわたって水に削られ磨かれた、滑らかで柔らかな表面も特徴です。月明洞自然聖殿を訪れた水石の専門家たちも感嘆しています。"]}, {"p": ["では、月明石はどのようにして月明洞自然聖殿に来ることになったのでしょうか。"]}, {"p": ["先生は以前から、月明洞の地形に似た石を得たいと祈ってこられました。神様の御心が込められた月明洞自然聖殿を、縮小版のように一目で見ながら教えるためでした。"]}, {"p": ["そのような中、先生は祈りの最中に魂で見た水石の姿を絵に描き、弟子である水石家に見せて、このような水石を探してみるように言われました。水石家はその絵を見た瞬間、4年前に慶州で見た一つの水石作品を思い出しました。"]}, {"p": ["その水石が正確にどこにあるのかも分からないまま慶州へ向かった水石家は、聖霊様の導きによって、わずか20分でその水石を発見しました。その後、石の持ち主の心が動かされ、異例の価格で水石を手に入れることができ、ついに月明洞自然聖殿へ運ばれてきました。"]}, {"p": ["このように、自分の時ではなく神様の時に合わせて行なうとき、行なうことがうまくいくという教訓も、月明石の経緯の中に込められています。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/wolmyeongseok.ja.v2.m4a", "audioDur": 350.6}, "zh": {"name": "月明石", "alias": "", "body": [{"p": ["這顆奇石是在2026年5月石頭慶典期間，月明洞自然聖殿新進的庭園石，出產自以美麗庭園石產地聞名的印尼。老師向賜下這顆奇石的聖靈懇切祈求，逐一仔細察看後，找出了二十個優點，讓這顆奇石變得更有價值。"]}, {"p": ["首先，它最大的優點，就是具備了長白山天池的形像與模樣。這種型態的自然石因為不容易找到，所以被評價為更珍貴的奇石。", "它的形像與月明洞自然聖殿地形形像中長白山天池的地形相似。月明洞開闢的四條道路，以及星峰亭、圓山與迴谷等地形都顯現在奇石上。因此，這顆石頭被命名為「月明石」。"]}, {"p": ["此外，月明石內部凹陷呈現橢圓形，相當神祕，因為水流在數萬年間以極快的速度旋轉沖刷，才雕琢出如今這般模樣。"]}, {"p": ["月明石上還有歷經漫長歲月的沖刷而自然形成的七座圓形山峰和八處可以蓄水的水坑。其中最大的水坑，裡面可以容納一百公升以上的水，深度足以容納三名成人，內側甚至有山水景石形像，增添神祕色彩。"]}, {"p": ["不僅如此，月明石中還隱藏著兩種酷似人體的形像。請您親自找找看。"]}, {"p": ["月明石長3.5公尺、高1.5公尺、寬2.5公尺，重量高達14.8噸，體積龐大、比例勻稱、硬度卓越，另一個特點是表面經數萬年水流沖刷雕琢，非常滑順柔和，連造訪月明洞的奇石專家們也讚嘆不已。"]}, {"p": ["那麼，月明石究竟是如何來到月明洞自然聖殿的呢？"]}, {"p": ["老師從很久以前就為了尋求酷似月明洞地形的石頭而持續禱告。這是為了在教導時讓人一眼就能看見蘊含　神旨意的月明洞自然聖殿樣貌縮小版。"]}, {"p": ["就在禱告的過程中，老師畫出了他以魂體所見到的奇石，拿給身為奇石專家的弟子看，並交代他去尋找像這樣的奇石。那位專家弟子看過那幅畫後，立刻就想起了四年前曾在慶州看過的一件奇石作品。"]}, {"p": ["那位專家弟子根本不知道這顆石頭確切在何處就直接奔向慶州，在聖靈的引領之下，僅僅花了二十分鐘就奇蹟般地再次找到了這顆奇石。後來，石頭主人的內心得到感動，我們才能以破天荒的優惠價格購入奇石，最終它進駐月明洞自然聖殿此地。"]}, {"p": ["也就是說，當我們不是在自己的時機，而是搭配　神的時機行動時，所做的事情就會順利。在月明石的故事中蘊含這樣的教誨。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/wolmyeongseok.zh.v1.m4a", "audioDur": 368.0}}, "audio": "/sayeon/stones/audio/101-guide.mp3", "audioDur": 326.6}, {"no": 15, "id": "seonghwaseok", "name": "성화석", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/seonghwaseok-1.v3.webp", "w": 900, "h": 506}], "body": [{"p": ["필리핀에서 가져온 이 수석은 활활 타오르는 횃불을 연상시키는 모습에서 ‘성화석’이라는 이름이 붙었습니다.", "힘차게 타오르는 횃불은 새 시대의 말씀을 듣고 하나님을 향한 사랑으로 뜨겁게 살아가는 젊은이들을 상징합니다."]}, {"p": ["또한 성화석의 위로 뾰족하게 솟은 형상은 밀라노 두오모 대성당의 첨탑을 떠올리게 합니다.", "선생님이 성화석을 두고 쓰신 시는 하나님을 향한 사랑에 불타는 작가의 마음이 고스란히 투영되어 있습니다. 베틀 위의 북처럼 이곳저곳을 오가며 팔려 다니던 성화석이 마침내 월명동 자연성전에 자리를 잡았듯이, 세상을 헤메던 우리도 하나님께서 정하신 때에 불러 주셨다는 의미를 담고 있습니다."]}, {"p": ["-성화석-", "너를 팔고 사니", "이리저리 나들며", "베틀 위의 북처럼 살던 너 아니냐"]}, {"p": ["너의 때가 됐다", "이 나라에 왔으니", "내게 온다"]}, {"p": ["네 아름답고 신기한 형상 모양", "격찬한다", "솟고 솟은 봉우리가 활활 타는 횃불 같다.", "나도 너 같이도 하나님 사랑에 타는 자다"]}, {"p": ["너 내게 오면", "천 년이나", "네 아름다움, 그 모양 형상 말해주고", "너를 수천만 년 흐르는 물에 깎이게 하여", "작품으로 창조한 하나님을 사랑하며", "너를 보며 같이 살으련다"]}], "i18n": {"en": {"name": "The Sacred Flame Rock", "alias": "", "body": [{"p": ["This ornamental rock, brought from the Philippines, was named “The Sacred Flame Rock” because its shape resembles a brightly blazing torch.", "The vigorously burning torch symbolizes young people who have heard the Word of the new time period and live with passionate love for God."]}, {"p": ["The pointed formations rising from the Sacred Flame Rock also resemble the spires of Milan Cathedral, also known as the Duomo di Milano."]}, {"p": ["In the poem Seonsaengnim wrote about the Sacred Flame Rock, the writer’s heart, burning with love for God, is vividly reflected. Just as the Sacred Flame Rock was sold and passed from place to place like a shuttle moving back and forth on a loom before finally finding its place in the Wolmyeongdong Natural Temple, it carries the meaning that we, too, who once wandered through the world, were called by God at the time He had appointed."]}, {"p": ["—The Sacred Flame Rock—"]}, {"p": ["You were bought and sold,", "going here and there,", "living like a shuttle on a loom, were you not?"]}, {"p": ["Your time has come.", "Now that you have come to this country,", "you are coming to me."]}, {"p": ["Your beautiful and wondrous form and shape—", "I praise it highly.", "Your soaring peaks", "are like a brightly blazing torch.", "I, too, like you,", "am one who burns with love for God."]}, {"p": ["When you come to me,", "for even a thousand years,", "I will speak of your beauty, your shape and form.", "I will love God,", "who created you as a work of art,", "having you carved by flowing water", "for tens of millions of years.", "Looking at you,", "I will live together with you."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/seonghwaseok.en.v1.m4a", "audioDur": 41.9}, "ja": {"name": "聖火石", "alias": "", "body": [{"p": ["フィリピンから運ばれてきたこの水石は、勢いよく燃え上がる松明を思わせる姿から、「聖火石」と名付けられました。"]}, {"p": ["力強く燃え上がる松明は、新しい時代の御言葉を聞き、神様への愛に燃えて熱く生きる若者たちを象徴しています。"]}, {"p": ["また、聖火石の上部に鋭くそびえる形象は、ミラノのドゥオーモ大聖堂の尖塔を思わせます。"]}, {"p": ["先生が聖火石について詠まれた詩には、神様への愛に燃える作者の心がそのまま映し出されています。機織り機の上を行き来する杼のように、あちらこちらへ渡り歩きながら売られていた聖火石が、ついに月明洞自然聖殿にその場所を得たように、世の中をさまよっていた私たちも、神様が定められた時に呼んでくださったという意味が込められています。"]}, {"p": ["―聖火石―"]}, {"p": ["あなたを売り買いするから", "あちらこちらへ行き来しながら", "機織り機の上の杼（ひ）のように生きてきたあなたではないか"]}, {"p": ["あなたの時が来た", "この国に来たから", "私のもとに来る"]}, {"p": ["あなたの美しく神秘的な形と形象を", "絶賛する", "高く高くそびえる峰が、勢いよく燃える松明のようだ", "私もあなたのように神様への愛に燃える者だ"]}, {"p": ["あなたが私のもとに来たら", "千年もの間", "あなたの美しさ、その形と形象を語り", "あなたを数千万年、流れる水に削らせ", "作品として創造された神様を愛しながら", "あなたを見つめ、共に生きていこう"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/seonghwaseok.ja.v2.m4a", "audioDur": 43.5}, "zh": {"name": "聖火石", "alias": "", "body": [{"p": ["這顆從菲律賓帶回來的奇石，其外型讓人聯想到熊熊燃燒的火把，因此被稱為「聖火石」。", "熊熊燃燒的火把，象徵著聆聽新時代話語、帶著對　神的愛火熱生活的年輕人。"]}, {"p": ["此外，聖火石上尖尖突起的形像，讓人聯想到米蘭大教堂的尖塔。"]}, {"p": ["老師為聖火石寫的詩，清楚地呈現出作者對　神的愛熊熊燃燒的心意。其中的含意是，聖火石起初就像織布機上的梭子那樣被賣到各處，最終落腳於月明洞自然聖殿；就像這樣，　神也在所定時機呼召曾在世上徘徊的我們。"]}, {"p": ["〈聖火石〉"]}, {"p": ["你曾幾經交易", "四處輾轉", "豈不像織布機上的梭子？"]}, {"p": ["而後時機成熟", "你來到這個國家", "便來到我這裡"]}, {"p": ["你那美麗神奇的樣貌", "令人歎為觀止", "一座座聳立隆起的山峰", "猶如熊熊燃燒的火炬", "我也像你這樣", "燃燒著對神的愛"]}, {"p": ["你若來到我這裡", "我將在千年之中", "述說你的美麗　你那樣貌", "愛著讓你經歷數千萬年水流雕琢", "將你創造成作品的神", "並且看著你　與你一同生活"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/seonghwaseok.zh.v1.m4a", "audioDur": 38.8}}, "audio": "/sayeon/stones/audio/104-guide.mp3", "audioDur": 40.1}, {"no": 16, "id": "saengmyeong-changjoseok", "name": "생명창조석", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/saengmyeong-changjoseok-1.v3.webp", "w": 900, "h": 597}], "body": [{"p": ["러시아에서 가져온 이 화강암 수석은 전체적으로 깔끔하고 예쁜 느낌을 자아냅니다. 처음에 이 돌은 ‘월명석의 세례요한 수석’으로 불리었습니다."]}, {"p": ["수석을 위에서 보면 가로 90cm, 세로 70cm의 큰 원과 가로 33cm, 세로 30cm의 작은 원이 서로 맞닿아있습니다. 이 두 원은 바로 ‘난자와 정자의 모양’을 상징합니다."]}, {"p": ["돌의 형상은 마치 정자가 난자를 뚫기 직전 뚫으려 하는 모습입니다. 이를 통해서 이 수석이‘생명창조석’이라는 이름을 가지게 되었습니다. 정자는 하나님을 상징하고 난자는 시대 신부들을 상징합니다."]}, {"p": ["한편 수석을 옆에서 보면 다양한 형상들을 더 발견할 수 있습니다. 좌청룡 우백호와 같은 형상도 가졌으며 S형상 에스라인을 볼 수 있습니다. 또한 한쪽에는 사람이 입을 벌리고 감탄하는 모습과 그 반대쪽에는 독수리 부리 형상을 볼 수 있습니다. 큰 구멍 두 개는 숫자 8의 형상을 가집니다. 숫자 8로 인해‘팔자가 피는 돌’을 의미하기도 합니다. 세계에서 하나님의 가장 귀한 장소인 월명동 자연성전에 온 수석처럼, 하나님의 새 역사에 온 사람들도 영육으로 팔자 핀 인생이 되었음을 시사합니다."]}], "i18n": {"en": {"name": "The Creation of Life Rock", "alias": "", "body": [{"p": ["This granite ornamental rock, brought from Russia, has an overall neat and beautiful appearance. It was originally called the “John the Baptist Rock of the Wolmyeong Rock.”"]}, {"p": ["When viewed from above, the rock features two circles touching each other: a larger circle measuring 90 centimeters wide and 70 centimeters long, and a smaller circle measuring 33 centimeters wide and 30 centimeters long. These two circles symbolize an egg and a sperm."]}, {"p": ["The rock's form resembles a sperm about to penetrate an egg. This resemblance gave the rock its name, the Creation of Life Rock. The sperm symbolizes God, while the egg symbolizes the brides of this time period."]}, {"p": ["When viewed from the side, the rock reveals even more images. It has formations resembling the Blue Dragon on the left and the White Tiger on the right, as well as an S-shaped curve. On one side, there is an image resembling a person with their mouth open in amazement, while on the opposite side, a formation resembling an eagle's beak can be seen."]}, {"p": ["The two large holes form the shape of the number 8. Because of its resemblance to the number 8, the rock is also said to symbolize a turn for the better in one's fortune.", "(Translator's Note: In Korean, the number eight is pronounced pal and is represented by the Chinese character 八. The word palja (八字) has two meanings: a person's fate or fortune, and the shape of the Chinese character 八 (eight). This play on words connects the rock's resemblance to the number eight with the Korean expression paljaga pida, meaning “to have one's fortune take a turn for the better.”)"]}, {"p": ["Just as this ornamental rock was brought to the Wolmyeongdong Natural Temple, God's most precious place in the world, those who have come into God's new history have also experienced a turn for the better in their lives, both spiritually and physically."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/saengmyeong-changjoseok.en.v1.m4a", "audioDur": 100.5}, "ja": {"name": "生命誕生石", "alias": "", "body": [{"p": ["ロシアから運ばれてきたこの花崗岩の水石は、全体的にすっきりとした美しい印象を与えます。当初、この石は「月明石のバプテスマのヨハネの水石」と呼ばれていました。"]}, {"p": ["水石を上から見ると、横90センチ、縦70センチの大きな円と、横33センチ、縦30センチの小さな円が互いに接しています。この二つの円は、「卵子と精子の形」を象徴しています。"]}, {"p": ["石の形象は、まるで精子が卵子を突き破ろうとする直前の姿のように見えます。この形象から、この水石は「生命創造石」と名付けられました。精子は神様を象徴し、卵子は時代の新婦たちを象徴しています。"]}, {"p": ["一方、水石を横から見ると、さらにさまざまな形象を発見することができます。左青龍・右白虎のような形象を持ち、S字形の美しいラインも見ることができます。また、一方には人が口を開けて感嘆している姿があり、その反対側には鷲のくちばしの形象を見ることができます。"]}, {"p": [{"t": "二つの大きな穴は、数字の「8」の形象をしています。この「8」から、「運が開ける石」という意味も持っています。世界で最も貴い神様の場所である月明洞自然聖殿にやって来たこの水石のように、神様の新しい歴史に来た人々も、霊肉ともに運が開けた人生となったことを示しています。", "em": "「運が開ける石」"}]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/saengmyeong-changjoseok.ja.v2.m4a", "audioDur": 107.0}, "zh": {"name": "生命創造石", "alias": "", "body": [{"p": ["這顆是從俄羅斯帶回來的花崗岩奇石，整體散發出一種乾淨俐落又美麗的感覺。起初，這顆石頭被命名為「月明石的施洗約翰奇石」。"]}, {"p": ["從上方俯看這顆奇石，可以看到一個橫向90公分、縱向70公分的大圓，以及一個橫向33公分、縱向30公分的小圓，兩個圓彼此相交。這兩個圓象徵的是「卵子與精子」。"]}, {"p": ["這顆石頭的形像，就如精子正要穿透卵子進入的模樣。因此，這奇石便有了「生命創造石」這名字。精子象徵　神，卵子則象徵時代眾新婦。"]}, {"p": ["另一方面，從側面觀看這奇石，能發現各種不同的形像。它有著如「左青龍、右白虎」的形像，還能看見S形曲線。此外，一側可以看見一個人張嘴讚歎的模樣，而在對面那一側則能看見鷹嘴形像。"]}, {"p": ["兩個大的孔洞呈現數字8的形狀，因此這也是顆意謂「八字變好」的石頭。正如這奇石來到世界上最寶貴之處，也就是　神的「月明洞自然聖殿」一般，這表示來到　神的新歷史的人們，靈肉的命運都已經變得大好。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/saengmyeong-changjoseok.zh.v1.m4a", "audioDur": 106.5}}, "audio": "/sayeon/stones/audio/103-guide.mp3", "audioDur": 104.1}, {"no": 17, "id": "gil-suseok", "name": "길 수석", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/gil-suseok-1.v3.webp", "w": 900, "h": 506}], "body": [{"p": ["‘길 수석’은 러시아 톈산산맥 해발 약 2,800m 고지에서 채취한 수석입니다. 크기는 작지만, 뒷면에 한글 ‘길’ 자를 닮은 무늬가 선명하게 나타나는 것이 특징입니다."]}, {"p": ["뿐만 아니라 이 수석에는 월명동 자연성전에서 대둔산 방향으로 이어지는 길인 ‘성령길’형상이 무늬로 새겨져 있습니다. 실제 성령길의 굽이굽이 이어지는 길의 각도와 위치, 방향까지 유사하게 나타나 놀라움을 자아냅니다.먼 러시아 산지에서 온 작은 수석에 ‘길’ 자와 성령길을 연상시키는 형상이 함께 나타난다는 점에서, 하나님의 신비 오묘한 역사를 드러냅니다."]}], "i18n": {"en": {"name": "The Path Rock", "alias": "", "body": [{"p": ["The Path Rock is an ornamental rock collected at an altitude of approximately 2,800 meters in the Tian Shan Mountains of Russia. Although small in size, it is distinguished by a clearly visible pattern on its back resembling the Korean character 길 (gil), meaning “path.”"]}, {"p": ["In addition, the rock features a pattern resembling the Holy Spirit Path, a winding path that extends from the Wolmyeongdong Natural Temple toward Mt. Daedun. Remarkably, the pattern closely resembles the actual path, even in the angles, positions, and directions of its many twists and turns."]}, {"p": ["The fact that this small ornamental rock, brought from the distant mountains of Russia, bears patterns resembling both the Korean character for “path” and the Holy Spirit Path reveals the mysterious and profound nature of God's works."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/gil-suseok.en.v1.m4a", "audioDur": 71.6}, "ja": {"name": "道の水石", "alias": "", "body": [{"p": [{"t": "「道の水石」は、ロシアの天山山脈、標高約2,800メートルの高地で採取された水石です。小さな水石ですが、裏面にハングルの「길（道）」という文字に似た模様が鮮明に現れていることが特徴です。", "em": "「길（道）」"}]}, {"p": ["さらにこの水石には、月明洞自然聖殿からテドゥン山方向へと続く「聖霊道」を思わせる形象が模様として刻まれています。実際の聖霊道の曲がりくねった道の角度や位置、方向まで似ており、驚きを感じさせます。"]}, {"p": [{"t": "遠いロシアの山地から来た小さな水石に、「길（道）」という文字と聖霊道を思わせる形象が共に現れているところに、神様の神秘で奥妙な歴史が現れています。", "em": "「길（道）」"}]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/gil-suseok.ja.v2.m4a", "audioDur": 85.7}, "zh": {"name": "道路石", "alias": "", "body": [{"p": ["「道路奇石」採自俄羅斯天山山脈、海拔約2800公尺的高地。雖然體積不大，但背面有著酷似韓文「길（道路）」的清晰紋樣，此為一大特色。"]}, {"p": ["不僅如此，奇石上還看得到月明洞自然聖殿往大芚山方向的「聖靈路」形像。路線蜿蜒的角度、位置、方向，都與實際的聖靈路極為相似，因此更令人驚歎。"]}, {"p": ["一顆來自遙遠俄羅斯山地的奇石，竟然同時出現「길」字與讓人聯想到聖靈路的形像，彰顯著　神深奧又神祕的動工。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/gil-suseok.zh.v1.m4a", "audioDur": 77.9}}, "audio": "/sayeon/stones/audio/105-guide.mp3", "audioDur": 78.9}, {"no": 18, "id": "ojikju-hananim-bawi", "name": "오직 주 하나님 바위", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/ojikju-hananim-bawi-1.v3.webp", "w": 900, "h": 600}], "body": [{"p": ["‘오직 주 하나님 바위’는 약수샘 앞에 세워진 약 30톤의 오석입니다. 가로 4.8m, 세로 3.4m 크기입니다.", "1996년 장마철, 거센 비가 내리던 중 ‘오직 주 하나님 바위’가 갑자기 넘어지는 일이 있었습니다. 당시 바위를 점검하던 제자는 바위가 넘어지기 직전, 굴 안에서 들려온 신비한 폭포 소리와 선생님의 목소리를 따라 자리를 옮겼고 위험을 피할 수 있었습니다.", "이 일은 자연성전 건축 과정 중 있었던 ‘생명을 지켜주신 하나님의 표적’ 가운데 하나입니다. 이후 바위는 지금의 위치로 옮겨 세워졌습니다.바위의 정면에는 금빛으로 ‘오직 주 하나님’이라는 글귀가 새겨져 있습니다."]}, {"p": ["‘오직 주 하나님’은 선생님의 신앙고백이자 그에게 신앙을 배우는 제자들의 고백이기도 합니다.", "근본자 하나님과 성령님과 성자가 우리를 매일 돕고 함께 하시니 우리도 이 시대를 향한 하나님의 뜻을 알고 하나님의 창조목적을 매일 이루면서 살아가야 합니다."]}], "i18n": {"en": {"name": "“Only the Lord God” Rock", "alias": "", "body": [{"p": ["The “Only the Lord God” Rock is a black stone weighing approximately 30 tons, standing in front of the Medicinal Water Spring. It measures 4.8 meters wide and 3.4 meters high."]}, {"p": ["During the rainy season of 1996, the “Only the Lord God” Rock suddenly toppled over amid heavy rainfall. Just before the rock fell, a disciple who was inspecting it heard the mysterious sound of a waterfall coming from inside the cave, along with Seonsaengnim’s voice. Following the voice, the disciple moved away and was able to escape danger.", "This incident was one of the signs of God’s protection of life that occurred during the construction of the Natural Temple.", "The rock was later moved and erected in its present location."]}, {"p": ["The words “Only the Lord God” are engraved in gold on the front of the rock."]}, {"p": ["“Only the Lord God” is Seonsaengnim’s confession of faith, as well as the confession of the disciples who learn faith from him.", "God, the Holy Spirit, and the Holy Son, the fundamental beings, help us and remain with us every day. Therefore, we too must live each day understanding God’s will for this era and fulfilling God’s purpose of creation."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/ojikju-hananim-bawi.en.v1.m4a", "audioDur": 139.4}, "ja": {"name": "ひたすら主神様の岩", "alias": "", "body": [{"p": ["「ひたすら主神様の岩」は、薬水の泉の前に立てられている約30トンの烏石です。大きさは横4.8メートル、縦3.4メートルです。"]}, {"p": ["1996年の梅雨の時期、激しい雨が降る中、「ひたすら主神様の岩」が突然倒れる出来事がありました。"]}, {"p": ["当時、岩を点検していた弟子は、岩が倒れる直前、洞窟の中から聞こえてきた神秘的な滝の音と先生の声に従ってその場を移動し、危険を避けることができました。"]}, {"p": ["これは、月明洞自然聖殿の建設過程で起きた「命を守ってくださった神様のしるし」の一つです。その後、岩は現在の場所へ移され、立てられました。"]}, {"p": [{"t": "岩の正面には、金色で「ひたすら主神様」という文字が刻まれています。", "em": "「ひたすら主神様」"}]}, {"p": ["「ひたすら主神様」は、先生の信仰告白であると同時に、先生から信仰を学ぶ弟子たちの告白でもあります。"]}, {"p": ["根本者である神様と聖霊様と御子が、私たちを毎日助け、共にしてくださっているので、私たちもこの時代に向けた神様の御心を知り、神様の創造目的を毎日成し遂げながら生きていかなければなりません。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/ojikju-hananim-bawi.ja.v2.m4a", "audioDur": 165.8}, "zh": {"name": "唯有主神石", "alias": "", "body": [{"p": ["「唯有主　神石」是豎立在山泉水前方、重約30噸的烏石，長4.8公尺、寬3.4公尺。"]}, {"p": ["1996年梅雨季，連續下了好幾天的暴雨，某一天「唯有主　神石」突然傾倒。", "當時正在檢查石頭的弟子在石頭傾倒前，聽見洞穴裡傳來神祕的瀑布流水聲，以及老師的聲音，他便跟著那聲音移動，因此才得以避開危險。", "這是在建設自然聖殿的過程中，「　神拯救生命的神蹟」之一。", "之後，這顆石頭就被搬移到如今的位置上豎立。"]}, {"p": ["石頭的正面刻著金色的「唯有主　神」字樣。"]}, {"p": ["「唯有主　神」是老師的信仰告白，也是向老師學習信仰的弟子們的告白。", "根本者　神、聖靈、聖子每天都幫助我們並同在，我們應當瞭解　神對這時代的旨意，每天達成　神的創造目的。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/ojikju-hananim-bawi.zh.v1.m4a", "audioDur": 141.9}}, "audio": "https://grand-pasca-8d267f.netlify.app/audio/ojikju-hananim-bawi.v4.m4a", "audioDur": 143.5}, {"no": 19, "id": "100ton-sansuhwa-jogakdol", "name": "100톤 산수화 조각돌", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/100ton-sansuhwa-jogakdol-1.v3.webp", "w": 900, "h": 506}], "body": [{"p": ["‘100톤 산수화 조각돌’은 중국에서 온 돌로, 거대한 바위 표면에 마치 한 폭의 산수화를 그려 놓은 듯한 무늬가 나타나 있습니다."]}, {"p": ["선생님은 하나님께 영광이 될 더 좋은 돌을 찾기 위해 계속 살피고 연구하던 중 이 산수화 돌을 발견했습니다. 더 잘하려고 노력할수록 그다음에 해야 할 일과 더 좋은 방법이 보인다는 깨달음 속에서 찾게 된 돌입니다."]}], "i18n": {"en": {"name": "The 100-Ton Landscape Painting Carved Rock", "alias": "", "body": [{"p": ["The 100-Ton Landscape Painting Carved Rock was brought from China. Its massive surface features natural patterns that resemble a beautiful landscape painting."]}, {"p": ["Seonsaengnim discovered this rock while continually searching and researching to find better rocks that would bring greater glory to God. He found it through the realization that the more effort one makes to do things better, the more clearly one can see what needs to be done next and discover better ways to accomplish it."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/100ton-sansuhwa-jogakdol.en.v1.m4a", "audioDur": 43.4}, "ja": {"name": "100トン山水画彫刻石", "alias": "", "body": [{"p": ["「100トン山水画彫刻石」は中国から来た石で、巨大な岩の表面には、まるで一幅の山水画を描いたかのような模様が現れています。"]}, {"p": ["先生は、神様により大きな栄光を帰す、さらに良い石を探し求めて研究を続ける中で、この山水画の石を発見しました。"]}, {"p": ["より良くしようと努力すればするほど、次にすべきことや、さらに良い方法が見えてくるという悟りの中で見つけた石です。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/100ton-sansuhwa-jogakdol.ja.v2.m4a", "audioDur": 44.7}, "zh": {"name": "100噸山水畫景觀石", "alias": "", "body": [{"p": ["「百噸山水畫雕刻石」是來自中國的石頭，表面紋理宛如一幅山水畫。"]}, {"p": ["為了尋找能向　神獻上更大榮耀的好石頭，老師持續觀察、研究，過程中發現了這顆山水畫石。老師體會到，越努力想把事情做得更好，就越能清楚地看見下一步該做的事情，以及更好的方法；而這顆石頭，就是在這樣的過程中找到的。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/100ton-sansuhwa-jogakdol.zh.v1.m4a", "audioDur": 47.8}}, "audio": "https://grand-pasca-8d267f.netlify.app/audio/100ton-sansuhwa-jogakdol.v4.m4a", "audioDur": 43.9}, {"no": 20, "id": "163ton-bawi", "name": "163톤 바위", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/163ton-bawi-1.v3.webp", "w": 900, "h": 506}], "body": [{"p": ["‘163톤 바위’은 2016년 2월 월명동 자연성전에 들어온 대형 자연석입니다."]}, {"p": ["이 바위엔 꿈에서 시작된 특별한 사연이 있습니다. 꿈속에서 선생님은 사고 싶었던 돌을 얻지 못해 아쉬워하던 중, 더 좋은 돌을 발견하고 헐값에 가져오는 꿈을 꾸었습니다."]}, {"p": ["이후 2016년 2월, 꿈에서 본 것처럼 월명동 자연성전에 성자바위보다 더 큰 바위가 들어오게 되었습니다.", "바위를 운반하는 과정에서 금이 간 부분은 잘라내야 했습니다. 처음에는 속상했지만, 해당 부분을 제거하면서 돌의 무게가 운반 가능한 수준으로 조정되어 163톤의 바위를 무사히 월명동까지 옮길 수 있었습니다."]}, {"p": ["163톤 바위는 꿈이 현실로 이루어진 하나님 역사의 기쁨과 표적을 상징합니다. 기대대로 안 되더라도 실망하고 포기치 않고 끝까지 행해야, 하나님이 주시는 더 좋은 것을 얻습니다."]}], "i18n": {"en": {"name": "The 163-Ton Rock", "alias": "", "body": [{"p": ["The 163-Ton Rock is a massive natural rock that was brought to the Wolmyeongdong Natural Temple in February 2016."]}, {"p": ["This rock has a special story that began with a dream. In the dream, Seonsaengnim was disappointed because he could not obtain a rock he had wanted to purchase. However, he then discovered an even better rock and acquired it at an exceptionally low price."]}, {"p": ["Later, in February 2016, just as he had seen in his dream, a rock larger than the Holy Son Rock was brought to the Wolmyeongdong Natural Temple.", "During transportation, a cracked section of the rock had to be cut off. Although this was disappointing at first, removing that section reduced the rock's weight to a manageable level, allowing the 163-ton rock to be safely transported to Wolmyeongdong."]}, {"p": ["The 163-Ton Rock symbolizes the joy and signs of God's works through which a dream became reality. Even when things do not go as expected, we must not become discouraged or give up. By persevering and seeing things through to the end, we can obtain something even better from God."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/163ton-bawi.en.v1.m4a", "audioDur": 85.1}, "ja": {"name": "163トンの岩", "alias": "", "body": [{"p": ["「163トンの岩」は、2016年2月に月明洞自然聖殿に入ってきた巨大な自然石です。"]}, {"p": ["この岩には、夢から始まった特別な経緯があります。夢の中で先生は、買いたかった石を手に入れることができず残念に思っていたところ、さらに良い石を発見し、非常に安い値段で手に入れる夢を見ました。"]}, {"p": ["その後、2016年2月、夢で見たとおり、月明洞自然聖殿に御子岩よりもさらに大きな岩が入ってきました。"]}, {"p": ["岩を運搬する過程で、ひびが入っていた部分を切り落とさなければなりませんでした。最初は残念に思いましたが、その部分を取り除いたことで、岩の重さが運搬可能な重量に調整され、163トンもの巨大な岩を無事に月明洞まで運ぶことができました。"]}, {"p": ["163トンの岩は、夢が現実となった神様の歴史の喜びとしるしを象徴しています。期待どおりにならなくても、落胆して諦めず最後まで行なうことで、神様が与えてくださるさらに良いものを得ることができます。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/163ton-bawi.ja.v2.m4a", "audioDur": 91.3}, "zh": {"name": "163噸石", "alias": "", "body": [{"p": ["「163噸石」是2016年2月被運入月明洞自然聖殿的巨大自然石。"]}, {"p": ["這顆岩石背後有一段特別的故事，始於一段夢境。夢裡，老師因為沒得到原本想買的石頭而感到遺憾，那時竟然發現一顆更好的石頭，並以便宜的價格買回。"]}, {"p": ["之後，在2016年2月，正如夢中所見，有一顆比聖子石更巨大的岩石運入月明洞自然聖殿。", "在搬運過程中，必須切除有裂痕的部分。起初雖然難過，但去除那部分後，反而將岩石重量調整到能搬運的程度，最終得以安全地將這163噸石運進月明洞。"]}, {"p": ["163噸石象徵「夢境在現實中實現」的　神歷史的喜悅與神蹟。即使事情不如意，也不要失望、不要放棄，而是要堅持到底、繼續行動，這樣才能領受　神賜下的更好事物。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/163ton-bawi.zh.v1.m4a", "audioDur": 99.6}}, "audio": "https://grand-pasca-8d267f.netlify.app/audio/163ton-bawi.v4.m4a", "audioDur": 83.1}, {"no": 21, "id": "doksuri-goeseok", "name": "독수리 형상 괴석", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/doksuri-goeseok-1.v3.webp", "w": 900, "h": 506}], "body": [{"p": ["여러 군데 파이고 구멍 난 돌을 괴석이라고 합니다. 특히 이‘독수리 형상 괴석’은 20톤에 100개 이상의 구멍이 형성된 독특한 모습의 괴석으로, 월명동 자연성전의 괴석작품 중 최고의 작품입니다."]}, {"p": ["어느날 선생님은 지난 날 성삼위와 예수님이 베풀어주신 은혜를 떠올리며 감사드렸습니다. 그러던 중 성령님의 감동에 따라 이 돌을 다른 위치에서 바라보자 마치 조각한 듯 선명한 독수리 형상이 보였습니다.", "괴석 좌측에는 비호같이 날아가다 방향을 꺾는 순간의 독수리, 상단에는 새끼 독수리가 어미를 쳐다보고 배우는 듯한 형상을 찾아볼 수 있습니다.독수리는 하나님과 성령님, 메시아 예수님과 사명자를 상징합니다.", "존재물에서 핵을 찾으면 그 가치도 더욱 빛나고 커집니다. 이처럼 자신의 장점을 찾고, 형제의 장점도 발견해 서로 말해주는 것이 중요합니다. 나아가 성경과 시대 말씀, 성삼위와 예수님, 그 육이 된 사명자의 가치도 깊이 깨닫고 발견해야 합니다."]}], "i18n": {"en": {"name": "The Eagle-Shaped Oddly Shaped Rock", "alias": "", "body": [{"p": ["Rocks with hollows and holes in various places are called oddly shaped rocks. The Eagle-Shaped Oddly Shaped Rock, in particular, weighs 20 tons and has a unique appearance, with more than 100 holes. It is considered the finest among the oddly shaped rock artworks at the Wolmyeongdong Natural Temple."]}, {"p": ["One day, Seonsaengnim recalled the grace that the Holy Trinity and Jesus had bestowed upon him in the past and gave thanks. Then, inspired by the Holy Spirit, he looked at the rock from a different position and saw a clearly defined image of an eagle, as though it had been sculpted."]}, {"p": ["On the left side of the rock, there is an image of an eagle suddenly changing direction while flying swiftly through the air. At the top, another formation resembles a young eagle looking up at its mother and learning from her.", "The eagle symbolizes God, the Holy Spirit, Jesus the Messiah, and the Man of Mission."]}, {"p": ["Discovering the core of something makes its value shine even brighter and grow greater. Likewise, it is important to recognize our own strengths, discover the strengths of our brothers and sisters, and share what we have discovered with one another.", "Furthermore, we must discover and deeply realize the value of the Bible, the Word of this time period, the Holy Trinity and Jesus, and the Man of Mission who has become their physical body."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/doksuri-goeseok.en.v1.m4a", "audioDur": 107.4}, "ja": {"name": "鷲の形象の怪石", "alias": "", "body": [{"p": ["あちこちがえぐれ、穴が開いている石を「怪石」といいます。中でもこの「鷲の形象の怪石」は、重さ20トン、100個以上の穴が形成された独特な姿を持つ怪石で、月明洞自然聖殿の怪石作品の中でも最高の作品です。"]}, {"p": ["ある日、先生はこれまで聖三位とイエス様が施してくださった恵みを思い起こし、感謝を捧げていました。その時、聖霊様の感動に従ってこの石を別の位置から眺めると、まるで彫刻したかのように鮮明な鷲の形象が見えました。"]}, {"p": ["怪石の左側には、素早く飛んでいた鷲が方向を変える瞬間の姿があり、上部には、子鷲が親鷲を見つめながら学んでいるかのような形象を見ることができます。"]}, {"p": ["鷲は、神様と聖霊様、メシアであるイエス様、そして使命者を象徴しています。"]}, {"p": ["存在物の中から核心を見つければ、その価値はいっそう輝き、大きくなります。このように、自分の長所を見つけ、兄弟の長所も発見して互いに伝え合うことが大切です。"]}, {"p": ["さらに、聖書と時代の御言葉、聖三位とイエス様、そしてその肉となった使命者の価値も、深く悟り、発見しなければなりません。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/doksuri-goeseok.ja.v2.m4a", "audioDur": 115.7}, "zh": {"name": "老鷹形象怪石", "alias": "", "body": [{"p": ["有多處凹陷且穿孔的石頭，被稱為怪石。而這顆「老鷹形像怪石」重20噸，有超過100個孔洞，外形尤為獨特，是月明洞自然聖殿怪石作品中最頂級的作品。"]}, {"p": ["某天，老師因為回想起過去聖三位和耶穌施予的恩典而獻上感謝。就在那時，老師在聖靈的感動之下，從另一個位置觀看這顆石頭。那一瞬間，宛如雕刻般清晰的老鷹形像映入眼簾。"]}, {"p": ["在怪石左側，可以看見如飛虎般快速飛翔的老鷹瞬間轉向的模樣；往上方看，還能看見一隻小老鷹形像，彷彿在仰望並學習母鷹。老鷹象徵　神、聖靈、彌賽亞耶穌與使命者。"]}, {"p": ["若在存在物中找到核心，其價值也會更提升、更發光。就像這樣，要尋找自己的長處，也要發現弟兄的長處，然後彼此稱讚，這是非常重要的。然後要更進一步地，深刻體會並發現聖經、時代話語、聖三位、耶穌，以及其肉體使命者的價值。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/doksuri-goeseok.zh.v1.m4a", "audioDur": 111.5}}, "audio": "/sayeon/stones/audio/9-guide.mp3", "audioDur": 105.7}, {"no": 22, "id": "chogajip-dol", "name": "초가집돌", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/chogajip-dol-1.v3.webp", "w": 900, "h": 600}], "body": [{"p": ["선생님이 어린 시절 살던 낡은 초가집을 닮은 이 돌은 하나님의 귀한 사연이 있습니다. 다 허물어져 가는 집이었지만, 기념이 될 만한 사진 한 장 남기지 못해 아쉬워하던 선생님에게 주신 귀한 선물입니다."]}, {"p": ["월명동 돌 작업이 한창이던 어느 날, 선생님은 약수샘 기도굴 위의 구멍을 막을 돌을 찾았습니다. 여러 돌을 맞춰 보았지만 모두 맞지 않았고, 멀리 중말거리에서 가져온 돌마저 사용할 수 없어 운동장 한편에 놓아두었습니다."]}, {"p": ["이튿날 그 돌을 다시 살펴보던 중, 어린 시절 살았던 낡은 초가집을 닮은 형상을 발견했습니다. 구멍에 맞지 않아 버려질 뻔했던 돌이 뜻밖의 귀한 형상석으로 발견된 것입니다."]}, {"p": ["만약 앞서 찾은 돌 가운데 하나라도 구멍에 맞았다면 이 돌을 찾으러 가지 않았을 것이고, 조금만 늦었어도 매립되어 다시는 발견하지 못했을 수 있습니다. 이를 통해 순탄치 않았던 과정 속에도 뜻이 있었음을 깨닫게 되었습니다. 하나님의 생각과 우리의 생각은 이처럼 다릅니다."]}, {"p": [{"q": "“곤고한 날에는 기도하고 생각하여 찾아라. 깊고 오묘한 뜻이 있다. 문제로만 여기지 말고, 문제를 통해 답을 얻으려고 하여라. 그러면 황금 같은 답을 얻는다”"}, "버리려던 돌을 새롭게 깨닫고 그 가치를 제대로 알아보니 멋있고 귀한 보물 돌이 되었듯, 자기 자신도 하찮게 여기지 말고, 그 속에 담긴 진정한 보화를 캐내기를 바랍니다."]}], "i18n": {"en": {"name": "The Thatched-Roof House Rock", "alias": "", "body": [{"p": ["This rock, which resembles the old thatched-roof house where Seonsaengnim lived during his childhood, has a precious story of God's works behind it. Although the old house had been falling apart, Seonsaengnim had always regretted not having even a single photograph of it as a keepsake. This rock was a precious gift from God to him."]}, {"p": ["One day, while rock landscaping work was in full swing in Wolmyeongdong, Seonsaengnim searched for a rock to cover a hole above the prayer cave at the Medicinal Water Spring. He tried fitting several rocks into the hole, but none of them fit. Even the rocks brought from distant Jungmalgeori could not be used, so they were left on one side of the sports field."]}, {"p": ["The following day, while examining the rocks again, Seonsaengnim discovered a formation resembling the old thatched-roof house where he had lived as a child. A rock that had nearly been discarded because it did not fit the hole was unexpectedly discovered to be a precious image rock."]}, {"p": ["If even one of the rocks he had found earlier had fit the hole, he would never have gone looking for this rock. Had he arrived even a little later, it might have been buried and never discovered again. Through this experience, he came to realize that there had been a will even in the difficulties he had encountered. This illustrates how God's thoughts differ from our own."]}, {"p": [{"q": "\"When you face days of hardship, pray, think, and search. There is a deep and mysterious purpose behind it. Do not regard difficulties merely as problems. Instead, seek to find answers through them. Then you will obtain answers as precious as gold.\""}, "Just as a rock that was nearly discarded became a magnificent and precious treasure when its true value was discovered and properly recognized, may you also refrain from regarding yourself as insignificant and uncover the true treasure hidden within you."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/chogajip-dol.en.v1.m4a", "audioDur": 156.2}, "ja": {"name": "藁葺き屋の石", "alias": "", "body": [{"p": ["先生が幼い頃に暮らしていた古い藁葺き屋に似たこの石には、神様の貴い経緯があります。今にも崩れそうな家でしたが、記念となる写真を一枚も残すことができず、残念に思っていた先生に与えられた貴い贈り物です。"]}, {"p": ["月明洞で岩の作業が盛んに行われていたある日、先生は薬水の泉の祈りの洞窟の上にある穴を塞ぐための石を探しました。いくつもの石を合わせてみましたが、どれも合わず、遠くチュンマルコリから運んできた石さえ使うことができず、運動場の片隅に置いておきました。"]}, {"p": ["翌日、その石をもう一度よく見ていたところ、幼い頃に暮らしていた古い藁葺き屋に似た形象を発見しました。穴に合わず、捨てられそうになっていた石が、思いがけず貴い形象石として発見されたのです。"]}, {"p": ["もし先に見つけた石のうち一つでも穴に合っていたなら、この石を探しに行くことはなかったでしょう。また、もう少し遅ければ埋められて、二度と発見できなかったかもしれません。このことを通して、思いどおりにいかなかった過程にも御心があったことを悟るようになりました。神様の考えと私たちの考えは、このように異なります。"]}, {"p": [{"q": "「苦しい日には祈り、考えて探しなさい。深く奥妙な御心がある。問題とだけ考えず、問題を通して答えを得ようとしなさい。そうすれば、黄金のような答えを得る。」"}]}, {"p": ["捨てようとしていた石も、新たに悟ってその価値を正しく見いだすと、素晴らしく貴い宝の石となりました。そのように、自分自身のことも取るに足りない存在だと思わず、その中に秘められた真の宝を掘り出してみてください。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/chogajip-dol.ja.v2.m4a", "audioDur": 174.7}, "zh": {"name": "茅草屋石", "alias": "", "body": [{"p": ["這顆石頭酷似老師小時候住的老舊茅草屋，有著　神寶貴的故事。雖是幾近坍塌的房屋，卻連一張能作為紀念的照片都沒有，令老師深感遺憾。因此，　神將這份寶貴的禮物賜給了老師。"]}, {"p": ["在月明洞如火如荼地進行石頭工程的某一天，為了堵住山泉水禱告洞上方的孔洞，老師尋找並比對了多顆石頭，卻沒有一顆契合。最後甚至從遙遠的中馬村搬石頭回來，但連那些石頭都派不上用場，只好放置在運動場的一側。"]}, {"p": ["隔天，老師再次觀察某一顆石頭，發現它的形像竟然酷似老師小時候住過的老舊茅草屋。沒想到這顆原本不適合孔洞、差點被丟棄的石頭，竟然是珍貴的形像石。"]}, {"p": ["假如在先前找的石頭裡，有一顆適合那個孔洞，哪怕只有一顆，老師也不會尋找其他石頭；而若是稍微再晚一點，這顆石頭可能就被掩埋而無法被發現。透過這件事，老師體會到，即使過程不順利，也還是有旨意。就像這樣，　神的想法與我們的想法不同。"]}, {"p": [{"q": "「在遭患難的日子禱告並思想，如此來尋找吧！其中有深而奧妙的旨意。不要只把它看成問題，還要藉由問題得到答案。如此就會得到黃金般的答案。」"}, "本來要被丟棄的石頭，因為人重新體會並正確瞭解其價值，反而成了帥氣又珍貴的寶物石；同樣地，希望各位不要認為自己毫不起眼，而是要將自己裡面蘊含的真正寶藏挖掘出來。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/chogajip-dol.zh.v1.m4a", "audioDur": 171.4}}, "audio": "/sayeon/stones/audio/44-guide.mp3", "audioDur": 153.4}, {"no": 23, "id": "amnokgang-suseok", "name": "압록강에서 온 수석", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/amnokgang-suseok-1.v3.webp", "w": 900, "h": 507}], "body": [{"p": ["‘압록강에서 온 수석’은 자연이 빚어낸 조각 작품처럼 독특한 형태가 특징입니다.", "압록강에서 선생님이 세우신 기도 조건에 하나님께서 주신 기념돌입니다."]}, {"p": ["2006년 당시 선생님은 북한 신의주가 바라보이는 압록강변에 한 달간 머물며 한반도의 평화를 위해 기도했습니다. 압록강 철교를 오가는 열차와 강 건너 신의주의 모습을 바라보며 남과 북이 자유롭게 왕래하고 평화를 이루기를 간구했습니다. 그로부터 얼마 후 남한과 북한을 연결하는 화물열차 시범 운행이 합의됐고 평화의 분위기가 고조되기도 했습니다."]}, {"p": ["성경에서 여호수아가 요단강을 건넌 뒤 돌을 세워 하나님의 역사를 기억하게 했듯, ‘압록강에서 온 수석’에는 선생님이 한반도의 평화를 위해 드린 기도를 기념하는 의미가 담겨 있습니다."]}], "i18n": {"en": {"name": "The Ornamental Rock from the Yalu River", "alias": "", "body": [{"p": ["The Ornamental Rock from the Yalu River is distinguished by its unique form, resembling a sculpture shaped by nature itself. It is a commemorative stone that God gave Seonsaengnim in response to the prayer conditions he established by the Yalu River."]}, {"p": ["In 2006, Seonsaengnim spent a month on the banks of the Yalu River, overlooking Sinuiju in North Korea, praying for peace on the Korean Peninsula. As he watched trains crossing the Yalu River Railway Bridge and gazed across the river toward Sinuiju, he earnestly prayed that people from North and South Korea would be able to travel freely between the two countries and achieve peace. Some time later, an agreement was reached to conduct a trial run of freight trains connecting North and South Korea, and hopes for peace grew."]}, {"p": ["Just as Joshua set up stones after crossing the Jordan River to commemorate God's works, the Ornamental Rock from the Yalu River serves as a memorial to Seonsaengnim's prayers for peace on the Korean Peninsula."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/amnokgang-suseok.en.v1.m4a", "audioDur": 100.5}, "ja": {"name": "鴨緑江から来た水石", "alias": "", "body": [{"p": ["「鴨緑江から来た水石」は、自然がつくり上げた彫刻作品のような、独特な形が特徴です。先生が鴨緑江で立てた祈りの条件に対して、神様が与えてくださった記念の石です。"]}, {"p": ["2006年当時、先生は北朝鮮の新義州を望む鴨緑江沿いに1か月間滞在し、朝鮮半島の平和のために祈りました。鴨緑江の鉄橋を行き来する列車や、川の向こうに見える新義州を眺めながら、南と北が自由に行き来し、平和を成し遂げることを祈り求めました。その後しばらくして、韓国と北朝鮮を結ぶ貨物列車の試験運行が合意され、平和への機運が高まったこともありました。"]}, {"p": ["聖書でヨシュアがヨルダン川を渡った後、石を立てて神様の歴史を記憶させたように、「鴨緑江から来た水石」には、先生が朝鮮半島の平和のために捧げた祈りを記念する意味が込められています。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/amnokgang-suseok.ja.v2.m4a", "audioDur": 112.9}, "zh": {"name": "鴨綠江奇石", "alias": "", "body": [{"p": ["「來自鴨綠江的奇石」，其特色在於形態獨特，彷彿是被大自然打造而成的雕刻作品。", "這顆石頭是　神基於老師曾在鴨綠江立下禱告條件，而賜下的紀念石。"]}, {"p": ["2006年，老師在能望見北韓新義州的鴨綠江沿岸停留了一個月，並為韓半島的和平而禱告。老師望著鴨綠江鐵橋上來來往往的列車，以及江河對岸的新義州，懇求　神讓南北韓自由往來、達成和平。不久後，南北韓達成協議，試著開放連接兩地的貨運列車運行，和平的氣氛也一度高漲。"]}, {"p": ["正如聖經中約書亞渡過約旦河後立起石頭，使人紀念　神的作為那般；「來自鴨綠江的奇石」蘊含著老師為韓半島和平獻上禱告的紀念意義。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/amnokgang-suseok.zh.v1.m4a", "audioDur": 111.8}}, "audio": "https://grand-pasca-8d267f.netlify.app/audio/amnokgang-suseok.v4.m4a", "audioDur": 112.5}, {"no": 24, "id": "guyeon-gugok", "name": "구연구곡", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/guyeon-gugok-1.v3.webp", "w": 900, "h": 601}], "body": [{"p": ["구연구곡은 ‘아홉 개의 연못과 아홉 개의 계곡’이라는 뜻으로 계곡과 연못을 연상시키는 형상을 갖추고 있습니다. 구연구곡이라는 이름에 걸맞게 곳곳에서 다양한 자연 풍경을 발견할 수 있습니다."]}, {"p": ["성인의 팔이 들어갈 정도의 굴이 형성돼 있고, 마치 자연의 한 풍경을 그대로 옮겨놓은 듯한 모습을 보여줍니다. 산수경석으로도 분류되는 이 작품은 무게 18톤에 이르며, 석질은 상수도 초코석입니다."]}, {"p": ["구연구곡은 천지암과 함께 충주댐 공사 이전인 1977년 6월 남한강에서 발견된 정원석입니다. 당시 탐석가들은 남한강 상류부터 하류까지 2년여 동안 수석을 찾아다녔으며, 발견 이후에도 다섯 명이 4개월에 걸쳐 작업한 끝에 비로소 세상에 모습을 드러낼 수 있었습니다."]}, {"p": ["전해지는 이야기에 따르면, 당시 물 수위가 낮을 때 드럼통 120개를 띄워 사각 구조물을 만들고 대형 도르래 두 개를 연결한 뒤, 물 수위가 높아졌을 때 인력으로 도르래를 돌려 수석을 끌어올렸다고 합니다. 그만큼 채석 과정 자체가 쉽지 않았던 희귀 작품입니다."]}, {"p": ["그중 구연구곡은 우리나라 최초의 개인 수석관인 석초원을 설립한 고(故)한기택 박사의 애장품으로 알려져 있습니다. 수석인들 사이에서는 ‘전래석’으로 불리며, 한때 전세버스를 대절해 관람할 정도로 큰 명성을 얻었던 대표적인 정원석입니다."]}], "i18n": {"en": {"name": "Nine Ponds and Nine Valleys", "alias": "", "body": [{"p": ["Guyeongugok, or Nine Ponds and Nine Valleys, takes its name from its formations, which evoke nine ponds and nine valleys. True to its name, a variety of natural landscapes can be found throughout the rock."]}, {"p": ["The rock has cavities large enough for an adult's arm to fit inside, creating the impression of an entire natural landscape captured in stone. Also classified as a landscape rock, this artwork weighs 18 tons and is made of a type of stone known as Sangsudo Choco Stone."]}, {"p": ["Nine Ponds and Nine Valleys, along with Cheonjiam (Heaven Lake Rock), is a garden rock discovered in the Namhan River in June 1977, before the construction of Chungju Dam. At the time, rock collectors spent approximately two years searching for ornamental rocks along the Namhan River, from its upper reaches to its lower reaches. Even after the rocks were discovered, it took five people another four months of work before they could finally be brought to light."]}, {"p": ["According to accounts passed down from that time, when the water level was low, the collectors floated 120 drums to construct a rectangular platform and connected two large pulleys. Then, when the water level rose, they manually operated the pulleys to lift the rocks out of the water. The difficulty of this extraction process makes these rocks particularly rare artworks."]}, {"p": ["Among them, Nine Ponds and Nine Valleys is known to have been a treasured possession of the late Dr. Han Gi-taek, who founded Seokchowon, Korea's first privately owned ornamental rock museum. Among ornamental rock enthusiasts, it is known as a “jeollaeseok”, a rock with a storied past that has been passed down through the years. It became so famous that people once chartered buses specifically to come and see it, making it one of Korea's most celebrated garden rocks."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/guyeon-gugok.en.v1.m4a", "audioDur": 134.3}, "ja": {"name": "九淵九曲", "alias": "", "body": [{"p": [{"t": "九淵九谷は、「九つの淵と九つの谷」という意味で、谷や淵を思わせる形象を備えています。その名にふさわしく、随所にさまざまな自然の風景を見つけることができます。", "em": "「九つの淵と九つの谷」"}]}, {"p": ["大人の腕が入るほどの洞窟が形成されており、まるで自然の風景をそのまま移してきたかのような姿を見せています。山水景石にも分類されるこの作品は、重さ18トンに達し、石質は上水道チョコ石です。"]}, {"p": ["九淵九谷は天池岩と共に、忠州ダムの工事以前の1977年6月、南漢江で発見された庭園石です。当時、探石家たちは南漢江の上流から下流まで約2年間にわたって水石を探し歩き、発見後も5人が4か月にわたって作業した末、ようやく世にその姿を現しました。"]}, {"p": ["伝えられている話によると、当時、水位が低い時にドラム缶120個を浮かべて四角い構造物を作り、大型の滑車二つを連結しました。そして水位が上がった時に、人力で滑車を回して水石を引き上げたといいます。それほど採石の過程そのものが困難だった希少な作品です。"]}, {"p": ["その中でも九淵九谷は、韓国初の個人水石館である「石草園」を設立した故・韓基澤博士の愛蔵品として知られています。水石愛好家の間では「伝来石」と呼ばれ、かつては貸切バスを仕立てて見学に訪れるほど大きな名声を得た、代表的な庭園石です。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/guyeon-gugok.ja.v2.m4a", "audioDur": 129.7}, "zh": {"name": "九淵九谷", "alias": "", "body": [{"p": ["「九淵九谷」的意思是九個池塘和九條溪谷，這顆石頭具有的形像，讓人聯想到池塘與溪谷。正如「九淵九谷」這個名字，在這顆石頭的各處能發現多樣化的自然景觀。"]}, {"p": ["石頭的一處形成了可讓大人手臂探入的洞穴，宛如直接將自然景觀移到石頭上。被分類為山水景石的這件作品，重達18噸，質地是「上水道巧克力石」。"]}, {"p": ["「九淵九谷」和「天地(天池)岩」是在1977年6月忠州水庫施工前，於南漢江發現的庭園石。當時奇石探索專家們在兩年多的時間裡，從南漢江上游到下游，四處尋找奇石。發現這兩顆奇石後，又經過五個人歷時四個月的作業，才終於得以向世人展現其面貌。"]}, {"p": ["據說，當時是趁水位低的時候，把一百二十個油桶放在水面上，組成四方形的構造物，並連接兩個大型滑輪；等水位升高時，再以人力轉動滑輪把奇石拉上來。由此可見，這兩件作品光是採石過程就不容易，十分稀有。"]}, {"p": ["其中，「九淵九谷」據悉是我國第一座個人奇石館——石艸園的創立者、已故韓基澤博士的珍藏品，在奇石界被稱為「傳承石」（指古代先人珍藏、流傳至今的奇石），聲名遠播，甚至一度吸引人們包租遊覽車前來觀賞，是具有代表性的庭園石。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/guyeon-gugok.zh.v1.m4a", "audioDur": 146.7}}, "audio": "https://grand-pasca-8d267f.netlify.app/audio/guyeon-gugok.v4.m4a", "audioDur": 135.8}, {"no": 25, "id": "cheonjiam", "name": "천지암", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/cheonjiam-1.v3.webp", "w": 900, "h": 600}], "body": [{"p": ["이 정원석은 오른쪽에 있는 ‘구연구곡’과 가까운 곳에서 채석되었습니다. 중앙에는 약 35리터의 물이 고일 수 있는 큰 웅덩이가 형성돼 있으며, 좌측에는 수많은 산봉우리를 연상시키는 형상이 펼쳐져 있습니다."]}, {"p": ["천지암은‘백두산 천지’를 닮은 형상이라 현재의 이름이 붙었습니다. 특히 돌 전체가 남한강 초코석 특유의 주름으로 되어있어 수석가들의 감탄을 자아냅니다."]}, {"p": ["이에 뒷면을 포함하여 돌 전체를 볼 수 있도록 연출했습니다. 최근에는 항공사진을 통해 중앙의 물 고임 부분이 하트 모양을 이루고 있다는 사실도 확인됐습니다.", "또한 중앙부에는 왕의 의자를 연상시키는 형상이 자리해 보는 이들에게 경외감을 불러일으킵니다."]}, {"p": ["천지암의 원주인은 월명동 자연성전을 방문한 뒤 깊은 인상을 받았고, 이후 선생님을 소개받는 과정에서 두 사람이 같은 백마부대 출신이라는 사실이 드러났습니다. 이러한 인연을 계기로 천지암은 특별한 조건으로 월명동 자연성전에 들어올 수 있었습니다.", "국내에서도 손꼽히는 수준의 정원석 작품을 월명동 자연성전에서 만날 수 있게 된 것입니다."]}], "i18n": {"en": {"name": "Heaven Lake Rock", "alias": "", "body": [{"p": ["This garden rock was excavated near Nine Ponds and Nine Valleys, located to its right. At its center is a large basin that can hold approximately 35 liters of water, while its left side features formations reminiscent of numerous mountain peaks."]}, {"p": ["Cheonjiam (Heaven Lake Rock) was given its present name because of its resemblance to Heaven Lake on Mt. Baekdu. Its entire surface features the distinctive wrinkle-like patterns characteristic of Namhan River Choco Stone, inspiring admiration among ornamental rock enthusiasts."]}, {"p": ["The rock has therefore been arranged so that visitors can view it in its entirety, including its back. Recently, aerial photographs also revealed that the water-holding basin at its center forms the shape of a heart. In addition, a formation resembling a king's throne can be found in the central area, inspiring a sense of awe in those who see it."]}, {"p": ["The original owner of Heaven Lake Rock was deeply impressed after visiting the Wolmyeongdong Natural Temple. Later, when he was introduced to Seonsaengnim, it was discovered that they had both served in the same military division, the White Horse Division. This connection made it possible for Heaven Lake Rock to be brought to the Wolmyeongdong Natural Temple under special terms.", "As a result, one of Korea's finest garden rock artworks can now be appreciated at the Wolmyeongdong Natural Temple."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/cheonjiam.en.v1.m4a", "audioDur": 91.8}, "ja": {"name": "天池岩", "alias": "", "body": [{"p": ["この庭園石は、右側にある「九淵九谷」の近くで採石されました。中央には約35リットルの水がたまる大きなくぼみがあり、左側には数多くの山々の峰を思わせる形象が広がっています。"]}, {"p": ["天池岩は「白頭山の天池」に似た形象をしていることから、この名前が付けられました。特に石全体には、南漢江のチョコ石特有のしわ模様が現れており、水石愛好家たちを感嘆させます。"]}, {"p": ["そのため、裏面を含めて石全体を鑑賞できるように演出されています。最近では航空写真によって、中央の水がたまる部分がハート形をしていることも確認されました。また中央部には、王の椅子を思わせる形象があり、見る人に畏敬の念を抱かせます。"]}, {"p": ["天池岩の元の持ち主は、月明洞自然聖殿を訪れて深い感銘を受けました。その後、先生を紹介される中で、二人が同じ白馬部隊の出身であることが分かりました。この縁をきっかけに、天池岩は特別な条件で月明洞自然聖殿に入ってくることができました。"]}, {"p": ["こうして、韓国内でも指折りの庭園石作品を、月明洞自然聖殿で見ることができるようになりました。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/cheonjiam.ja.v2.m4a", "audioDur": 87.0}, "zh": {"name": "天地石", "alias": "", "body": [{"p": ["這顆庭園石是在右邊那顆「九淵九谷」的鄰近之處採掘的。中央形成了一個大水坑，可積蓄約35公升的水，左側形像則讓人聯想到綿延的山峰。"]}, {"p": ["天地(天池)岩因形像酷似「長白山天池」而得名。尤其整顆石頭布滿南漢江巧克力石特有的皺褶紋理，令奇石家們不禁讚歎。"]}, {"p": ["因此，為了讓各位在觀賞時能看見石頭整體甚至背面，才如此呈現。最近透過空拍圖確認到，中間蓄水的部分呈心形。", "此外，中央部位的形像讓人聯想到王座，令觀賞者心生敬畏。"]}, {"p": ["天地(天池)岩的前持有者在參觀月明洞自然聖殿後，留下深刻印象。之後，在弟子介紹老師時，偶然發現前持有者與老師同為白馬部隊的隊員。這樣的緣分成為契機，使天池岩能以特殊條件進入月明洞自然聖殿；而各位也才能在月明洞自然聖殿，遇見天地(天池)岩這顆在韓國也屈指可數的庭園石作品。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/cheonjiam.zh.v1.m4a", "audioDur": 91.0}}, "audio": "https://grand-pasca-8d267f.netlify.app/audio/cheonjiam.v4.m4a", "audioDur": 92.9}, {"no": 26, "id": "saengmyeongseok", "name": "생명석", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/saengmyeongseok-1.v3.webp", "w": 900, "h": 512}], "body": [{"p": ["이 수석은 길이 2m×높이 1m×두께 1m의 크기를 갖춘 정원석입니다."]}, {"p": ["생명석은 6가지의 좋은 점을 가지고 있습니다. 오랜 세월 물에 씻기고 다듬어져 수마가 잘 되어 있으며, 돌 자체가 강합니다. 산지는 남한강이며 좌우 대칭이 잘 맞고, 전체적인 형태에서는 황금비율을 찾아볼 수 있습니다. 또한 하나의 돌 안에서 여러 가지 형상을 발견할 수 있다는 점이 특징입니다."]}, {"p": ["생명석은 총 21가지의 형상을 지니고 있습니다.", "백두산 천지못과 같은 형상이 나타나며, 다섯 개의 봉우리도 볼 수 있습니다. 그 모습은 한 가정의 남자와 여자, 자녀들이 함께 있는 형상처럼 보이기도 하고, 사람의 손과 발을 상징하는 모습으로도 읽힙니다. 다섯 개의 봉우리는 5복을 상징하며, 독수리의 발톱과 새벽별, 생명나무를 연상시키는 형상도 담고 있습니다."]}, {"p": ["또한 하나님 앞에서 사람이 ‘아멘’ 하고 말씀을 듣고 있는 모습처럼 보이는 형상도 찾아볼 수 있습니다."]}, {"p": ["그러나 이 돌의 가장 좋은 점은 바로 ‘선생님을 통해 구했다’는 데 있습니다. 선생님은 지난 4월 돌 축제를 앞두고 성령님께 돌을 간구하셨습니다. 그러자 성령님은 합당한 사람을 통해 이 돌을 만나게 하시고, 선생님이 성령님의 시중을 들어 사게 하신 것입니다. 두 차례나 다른 곳에 팔릴 뻔했지만 마침내 월명동에 온 생명석의 사연은 앞으로 천년 동안 대대손손 전해질 것입니다."]}, {"p": ["생명석이 오랜 시간 닦이고 깎이며 지금의 모습을 갖춘 것처럼, 이와 같이 우리의 인생도 끊임없이 닦고 깎으며 갖추어 가야 함을 깨닫게 합니다. 강한 돌처럼 마음을 강하게 만들고, 손과 발 같이 부지런하고, 서로 하나가 되어 살아가야 한다는 메시지를 전하고 있습니다."]}], "i18n": {"en": {"name": "The Life Rock", "alias": "", "body": [{"p": ["This ornamental rock is a garden rock measuring 2 meters in length, 1 meter in height, and 1 meter in thickness."]}, {"p": ["The Life Rock has six outstanding qualities. It has been naturally smoothed and shaped by water over many years, and the stone itself is strong and durable. Originating from the Namhan River, it has excellent left-right symmetry, and its overall form exhibits the golden ratio. Another distinctive feature is the variety of images that can be discovered within this single rock."]}, {"p": ["The Life Rock contains a total of 21 recognizable images. Among them are a formation resembling Heaven Lake on Mt. Baekdu and five mountain peaks. These formations can also be interpreted as a family consisting of a man, a woman, and their children, or as representations of human hands and feet. The five peaks symbolize the Five Blessings. Other formations evoke an eagle's talons, the Morning Star, and the Tree of Life."]}, {"p": [{"t": "There is also a formation resembling a person listening to the Word before God and responding, \"Amen.\"", "em": "\"Amen.\""}]}, {"p": ["However, the rock's greatest quality lies in the fact that it was acquired through Seonsaengnim. Last April, ahead of the Rock Festival, Seonsaengnim prayed to the Holy Spirit for a rock. In response, the Holy Spirit led him to this rock through the right person and guided him in serving Her so that he could purchase it. Although the rock nearly sold to other buyers on two separate occasions, it ultimately arrived in Wolmyeongdong. The story of how the Life Rock came to Wolmyeongdong will be passed down from generation to generation for the next thousand years."]}, {"p": ["Just as the Life Rock acquired its present form through countless years of being smoothed and shaped, it reminds us that we, too, must continually refine and develop ourselves throughout our lives. It conveys the message that we should strengthen our hearts to be as strong as this rock, live diligently like the hands and feet reflected in its form, and live in unity with one another."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/saengmyeongseok.en.v1.m4a", "audioDur": 185.0}, "ja": {"name": "生命石", "alias": "", "body": [{"p": ["この水石は、長さ2メートル、高さ1メートル、厚さ1メートルの大きさを持つ庭園石です。"]}, {"p": ["生命石には六つの良い点があります。長い歳月にわたって水に洗われ、磨かれてきたため水磨がよくなされており、石そのものも強固です。産地は南漢江で、左右のバランスがよく整い、全体的な形には黄金比を見ることができます。また、一つの石の中からさまざまな形象を発見できることも特徴です。"]}, {"p": ["生命石には、全部で21種類の形象があります。", "白頭山の天池を思わせる形象があり、五つの峰も見ることができます。その姿は、一つの家庭の男性と女性、子どもたちが共にいるようにも見え、人の手足を象徴する姿として見ることもできます。五つの峰は五福を象徴し、鷲の爪や明けの明星、命の木を思わせる形象もあります。"]}, {"p": [{"t": "また、神様の前で人が「アーメン」と言いながら御言葉を聞いているように見える形象もあります。", "em": "「アーメン」"}]}, {"p": [{"t": "しかし、この石の最も良い点は、まさに「先生を通して得た」というところにあります。先生は今年4月の岩の祝祭を前に、聖霊様に石を求めて祈りました。すると聖霊様は、ふさわしい人を通してこの石に出会わせ、先生が聖霊様に仕えてこの石を購入するようにされました。二度も他の場所に売られそうになりながら、ついに月明洞にやって来た生命石の経緯は、これから千年にわたって代々語り継がれていくことでしょう。", "em": "「先生を通して得た」"}]}, {"p": ["生命石が長い歳月をかけて磨かれ、削られながら今の姿を備えたように、私たちの人生も絶えず磨き、削りながら自分自身をつくり上げていかなければならないことを悟らせてくれます。強い石のように心を強くし、手足のように勤勉に、そして互いに一つになって生きていかなければならないというメッセージを伝えています。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/saengmyeongseok.ja.v2.m4a", "audioDur": 193.9}, "zh": {"name": "生命石", "alias": "", "body": [{"p": ["這顆奇石是長2公尺、高1公尺、厚1公尺的庭園石。"]}, {"p": ["生命石具備六項優點。經水流長年沖刷雕琢、充分磨蝕，石頭本身相當堅固。產地是南漢江，左右對稱，而且整體形態符合黃金比例。此外還有一個特點，就是在一顆石頭上能發現多種形像。"]}, {"p": ["生命石共有二十一種形像。", "除了酷似長白山天池的形像外，也可看出五座山峰；還具有男人、女人與孩子們全家相聚的形像，以及象徵人類手指與腳趾形像。五座山峰象徵五福，也有著能讓人聯想到老鷹爪子、晨星、生命樹的形像。"]}, {"p": ["與此同時，還能在石頭上找到類似人們在　神面前邊聽話語邊說「阿們」的形像。"]}, {"p": ["然而，這顆石頭最大的優點，在於它是透過老師得來的。老師在今年四月舉辦奇石慶典前，求聖靈賜下石頭。於是聖靈透過合宜之人找到這顆石頭，並且看在老師伺候聖靈的份上，讓老師買下來。雖然石頭差點兩度被賣到別處，但最終還是來到了月明洞。這顆生命石的故事，將世世代代流傳千年。"]}, {"p": [{"t": "生命石經過漫長歲月的沖刷、雕琢，才形成如今的模樣；同樣地，我們的人生也要不斷沖刷、雕琢而越加完整。「每個人都要將內心造就得如堅硬石頭般堅強，並且像手與腳一樣勤奮，彼此成為一體來生活」，是這顆石頭所要傳遞的訊息。", "em": "「每個人都要將內心造就得如堅硬石頭般堅強，並且像手與腳一樣勤奮，彼此成為一體來生活」"}]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/saengmyeongseok.zh.v1.m4a", "audioDur": 184.0}}, "audio": "/sayeon/stones/audio/102-guide.mp3", "audioDur": 205.0}, {"no": 27, "id": "igeulseok", "name": "이글석", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/igeulseok-1.v3.webp", "w": 900, "h": 600}], "body": [{"p": ["이 수석은 가로 132cm, 세로 87cm, 두께 65cm의 크기로, 산지는 남한강이며 석질은 잿빛청석입니다. 돌에는 흰 줄이 나타나 있는데, 남한강에서 흰 줄이 있는 잿빛청석은 나오기 힘들어 매우 좋은 수석으로 여겨집니다."]}, {"p": ["이 수석은 전체적으로 잘생기고, 파워 있고, 깊이 찢어지고 잘 파인 모습이 돋보입니다. 수마 또한 잘 이루어져 석질과 색이 좋으며, 형과 질, 색을 모두 갖춘 좋은 돌입니다."]}, {"p": ["이 수석에서는 다양한 형상을 찾아볼 수 있습니다. 곧게 세워진 입석의 형태를 비롯하여 바위와 산수의 경관을 연상시키는 산수경석의 모습이 나타나며, 사람이나 동물, 사물 등 구체적인 대상을 닮은 우형석의 특징도 엿볼 수 있습니다. 특히 독수리를 연상시키는 형상이 뚜렷하게 나타나는 점이 이 수석의 특징입니다."]}, {"p": ["이 돌의 이름은 이러한 형상에서 따온 ‘이글석’입니다. 독수리의 부리와 눈, 좌우의 어깨에 해당하는 형상이 나타나 있어 ‘이글석’, 즉 ‘독수리석’이라 부릅니다."]}, {"p": ["자세히 살펴보면 또 다른 형상도 발견할 수 있습니다. 좌우 어깨 부분에는 귀가 있는 독수리의 형상이 나타나며, 오른쪽에는 독수리가 발톱으로 뱀의 머리를 움켜쥐고 있는 듯한 형상이 자리하고 있습니다."]}, {"p": ["독수리의 눈에 해당하는 부분에는 돌을 붙여 눈의 형상이 더욱 확연하게 보이도록 연출하였으며, 돌의 아래에는 금색 비단 천을 두어 작품을 연출하였습니다."]}, {"p": ["이 수석에는 특별한 사연도 담겨 있습니다. 1985년, 한 포크레인 기사가 남한강에서 작업하던 중 이 돌을 발견하였습니다. 이후 41년 만에 월명동 자연성전에 온 것입니다. 이때까지 하나님께서 이 돌을 지키신 것입니다."]}], "i18n": {"en": {"name": "The Eagle Rock", "alias": "", "body": [{"p": ["This ornamental rock measures 132 cm in width, 87 cm in height, and 65 cm in thickness. It originates from the Namhan River and is composed of ash-gray bluestone. White streaks run through the rock, a particularly rare feature in ash-gray bluestone from the Namhan River, making it a highly prized ornamental rock."]}, {"p": ["The rock has an impressive overall form, with a powerful appearance, deep fissures, and well-defined hollows. It has also been naturally smoothed by water over time, giving it excellent stone quality and color. It is an outstanding rock that possesses all three desirable qualities: form, stone quality, and color."]}, {"p": ["A variety of images can be discovered in this rock. Its upright form gives it the characteristics of a standing rock, while its formations also resemble rocky and mountainous landscapes, giving it the qualities of a landscape rock. It also exhibits the characteristics of an image rock, with formations resembling recognizable people, animals, and objects. Its most distinctive feature, however, is its clearly recognizable resemblance to an eagle."]}, {"p": ["The rock was named the Eagle Rock because of this resemblance. Its formations suggest an eagle's beak, eye, and left and right shoulders, giving rise to its name."]}, {"p": ["A closer look reveals additional images. Around its left and right shoulder areas, a formation resembling an eagle with ears can be seen. On the right side, another formation resembles an eagle grasping a snake's head with its talons."]}, {"p": ["A small stone has been attached to the area corresponding to the eagle's eye to make its shape more distinct. Gold-colored silk fabric has also been placed beneath the rock to enhance its presentation."]}, {"p": ["The Eagle Rock also has a special story behind it. In 1985, an excavator operator discovered the rock while working in the Namhan River. Forty-one years later, it finally arrived at the Wolmyeongdong Natural Temple. Throughout those years, God had protected this rock."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/igeulseok.en.v1.m4a", "audioDur": 141.1}, "ja": {"name": "イーグル石", "alias": "", "body": [{"p": ["この水石は、横132センチ、縦87センチ、厚さ65センチの大きさで、産地は南漢江、石質は灰色がかった青石です。石には白い筋が入っており、南漢江では白い筋の入った灰色がかった青石は産出されにくいため、非常に良い水石とされています。"]}, {"p": ["この水石は全体的に形が整っていて力強く、深く裂け、よくえぐられた姿が際立っています。水磨もよくなされており、石質と色も良く、形・質・色のすべてを備えた優れた石です。"]}, {"p": ["この水石からは、さまざまな形象を見つけることができます。まっすぐに立つ立石の形をはじめ、岩や山水の景観を思わせる山水景石の姿が現れており、人や動物、物など具体的な対象に似た偶形石としての特徴も見ることができます。中でも、鷲を思わせる形象がはっきりと現れていることが、この水石の大きな特徴です。"]}, {"p": ["この形象から、「イーグル石」と名付けられました。鷲のくちばしや目、左右の肩にあたる形象が現れていることから、「イーグル石」、すなわち「鷲石」と呼ばれています。"]}, {"p": ["さらに詳しく見ると、別の形象も発見できます。左右の肩の部分には耳のある鷲の形象が現れ、右側には、鷲が爪で蛇の頭をつかんでいるかのような形象があります。"]}, {"p": ["鷲の目にあたる部分には石を付け、目の形象がよりはっきりと見えるように演出しています。また、石の下には金色の絹布を敷き、作品をより引き立てています。"]}, {"p": ["この水石には、特別な経緯もあります。1985年、あるショベルカーの運転手が南漢江で作業をしていた際、この石を発見しました。そして41年の時を経て、月明洞自然聖殿にやって来ました。それまでの間、神様がこの石を守ってこられたのです。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/igeulseok.ja.v2.m4a", "audioDur": 148.2}, "zh": {"name": "老鷹石", "alias": "", "body": [{"p": ["這顆奇石長132公分、寬87公分、高65公分，產地是南漢江，質地是灰青石。石頭上有白色線條，而南漢江產出帶有白色紋樣的灰青石十分罕見，因此被視為上好的奇石。"]}, {"p": ["這顆奇石整體外形優美、充滿力量，深深的裂縫與凹陷處十分突出，而且被沖刷得非常完全，質地與色澤俱佳，是一顆兼具形像、質地、色澤的好石頭。"]}, {"p": ["在這顆奇石上可以找到多種形像，不僅有直立的石碑形態，以及讓人聯想到岩石與山水景觀的山水景石樣貌，還可窺見相似於人、動物或事物等具體對象的象形石特徵。尤其具有能讓人聯想到老鷹的清晰形像，更是這顆奇石的一大特徵。"]}, {"p": ["基於這樣的形像，將其取名為「Eagle石」。由於呈現出老鷹的喙、眼睛，以及左肩與右肩的形像，因此命名為「Eagle石」，也就是「老鷹石」。"]}, {"p": ["若仔細觀察，還可發現其他形像。左右肩部呈現出「有耳朵的老鷹」形像，而右側也有宛如老鷹以利爪抓住蛇頭的形像。"]}, {"p": ["老師為它裝飾點綴，在老鷹眼睛處貼上石頭，讓人能更確實地看出老鷹的眼睛形像；而石頭下方則舖了金綢緞，使這顆石頭更加光彩奪目。"]}, {"p": ["這顆奇石也蘊含著特別的故事。1985 年，一位挖土機司機在南漢江作業時發現了這顆石頭；之後隔了41年，它才進入月明洞自然聖殿，此前　神一直守護著它。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/igeulseok.zh.v1.m4a", "audioDur": 146.1}}, "audio": "https://grand-pasca-8d267f.netlify.app/audio/igeulseok.v4.m4a", "audioDur": 153.0}, {"no": 28, "id": "koppulso-bawi", "name": "코뿔소 바위", "alias": "", "summary": "", "place": "", "photos": [{"src": "https://grand-pasca-8d267f.netlify.app/images/koppulso-bawi-1.v3.webp", "w": 900, "h": 600}], "body": [{"p": ["코뿔소 바위는 선생님이 20대 때, 좋다고 늘 보던 돌이었습니다. 기도하니 옛날의 그 형상이 떠올라서 파게 되어 찾은 돌입니다. 흰 코뿔소 형상입니다."]}, {"p": ["코뿔소는 힘과 건강의 상징이자, 지상에서는 코끼리에 버금가는 큰 동물입니다. 특히 회백색을 띤 흰코뿔소는 다른 코뿔소보다 크기도 더 큽니다. 흰 코뿔소는 몸길이 3.6~5m, 어깨높이 1.6~2m, 몸무게 2,300~3,600kg에 달합니다."]}, {"p": ["이 바위는 머리와 몸통이 확실하게 구분되어 있고, 핵심인 뿔이 확실하게 드러나 있어 한눈에 봐도 코뿔소 형상입니다. 전체적으로 투명한 흰색인데, 배나 엉덩이 쪽의 얼룩은 코뿔소같이 자연스럽게 두었습니다. 원래 다리가 없었지만 2025년 돌을 붙여 다리처럼 연출을 해주었습니다."]}, {"p": ["좋은 작품돌은 평생에 하나 찾기도 어려울 만큼 귀합니다. 특히 월명동 자연성전의 형상석들은 하나님의 대걸작으로 귀한 사연을 품고 있습니다."]}, {"p": [{"q": "\"사고와 생각과 실천이 뚜렷한 자는 마치 형상석처럼 특별한 인간 작품이다.\""}]}, {"p": ["돌마다 각기 다른 개성과 가치가 있듯 자기 자신도 개성대로 귀한 자요, 다시는 없는 귀한 작품 인생들입니다. 각자 어떤 면의 작품인지 하나님께 간구하고 여쭤보며, 특별한 사연을 만드시길 바랍니다."]}], "i18n": {"en": {"name": "The Rhinoceros Rock", "alias": "", "body": [{"p": ["The Rhinoceros Rock is a stone that Seonsaengnim had always admired and frequently looked at when he was in his twenties. Years later, while praying, he recalled the rock's distinctive shape, which led him to excavate and rediscover it. The rock resembles a white rhinoceros."]}, {"p": ["Rhinoceroses symbolize strength and health and are among the largest land animals, second only to elephants. The white rhinoceros, which has a grayish-white appearance, is particularly large compared to other rhinoceros species. It measures approximately 3.6–5 meters in body length, stands 1.6–2 meters tall at the shoulder, and weighs between 2,300 and 3,600 kilograms."]}, {"p": ["The rock has a clearly defined head and body, and its most distinctive feature, the horn, stands out prominently, making its resemblance to a rhinoceros immediately recognizable. The rock is predominantly translucent white, while the natural markings around its belly and hindquarters have been left intact because they resemble those of a rhinoceros. Although the rock originally had no legs, additional stones were attached in 2025 to create the appearance of legs."]}, {"p": ["Fine ornamental rock artworks are so rare that finding even one in a lifetime is difficult. In particular, the image rocks at the Wolmyeongdong Natural Temple are God's great masterpieces, each with its own precious story."]}, {"p": [{"q": "\"Those whose reasoning, thoughts, and actions are clearly defined are extraordinary human masterpieces, just like image rocks.\""}, "Just as every rock has its own unique characteristics and value, each of us is precious in our own unique way—an irreplaceable work of art, the likes of which will never exist again. Pray to God and ask Him what kind of work of art you are, and strive to create your own extraordinary story.", "Just as every rock has its own unique characteristics and value, each of us is precious in our own unique way—an irreplaceable work of art, the likes of which will never exist again. Pray to God and ask Him what makes you a unique work of art, and strive to create your own extraordinary story."]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/koppulso-bawi.en.v1.m4a", "audioDur": 94.7}, "ja": {"name": "サイの岩", "alias": "", "body": [{"p": ["サイの岩は、先生が20代の頃から「良い石だ」と、いつも目を留めていた石でした。祈る中で昔見たその形象を思い出し、掘り出して発見した石です。シロサイの形象をしています。"]}, {"p": ["サイは力と健康の象徴であり、陸上ではゾウに次ぐほど大きな動物です。特に灰白色を帯びたシロサイは、他のサイよりも大きく、体長3.6～5メートル、肩までの高さ1.6～2メートル、体重2,300～3,600キログラムにも達します。"]}, {"p": ["この岩は、頭と胴体がはっきりと分かれており、核心となる角も鮮明に現れているため、一目見てもサイの形象だと分かります。全体的に透き通るような白色をしており、腹部や尻の部分の斑模様は、サイらしく自然な状態を生かしています。もともと脚はありませんでしたが、2025年に石を付け、脚のように見えるよう演出しました。"]}, {"p": ["良い作品石は、一生のうちに一つ見つけることさえ難しいほど貴重なものです。特に月明洞自然聖殿の形象石には、神様の大傑作として、それぞれ貴い経緯が込められています。"]}, {"p": [{"q": "「思考と考えと実践がはっきりしている人は、まるで形象石のような特別な人間作品だ。」"}]}, {"p": ["石の一つひとつに異なる個性と価値があるように、自分自身もそれぞれの個性のままに貴い存在であり、二度とない貴重な作品のような人生です。自分がどのような面で作品なのかを神様に祈り求め、尋ねながら、特別な経緯をつくっていくことを願います。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/koppulso-bawi.ja.v2.m4a", "audioDur": 101.3}, "zh": {"name": "犀牛石", "alias": "", "body": [{"p": ["「犀牛石」是老師二十多歲時就相中的石頭。之後在禱告時，腦中浮現曾經看過的那形像，經挖掘後找到了這顆石頭。它的形像是白犀牛。"]}, {"p": ["犀牛是象徵力量與健康的動物，尤其白犀牛是僅次於大象的大型陸生動物。尤其，呈灰白色的白犀牛，體型比其他種犀牛更大。白犀牛的體長3.6至5公尺，肩高1.6至2公尺，體重約為2300至3600公斤。"]}, {"p": ["在這顆岩石上，能清楚區分頭部與身體，連作為核心的角也相當明顯，所以一眼就能看出它具有犀牛形像。整體呈帶有透明感的白色，腹部與臀部有著跟犀牛一樣的自然紋理。原本沒有腿部，於是在2025年用石頭裝飾，替它黏上了腿部。"]}, {"p": ["好的作品石價值連城，寶貴到一輩子連一顆也難以尋得。尤其，月明洞自然聖殿的形像石都是　神的大傑作，各個都蘊含珍貴故事。"]}, {"p": [{"q": "「思考、想法與實踐清楚鮮明的人，就跟形像石一樣，是特殊的人作品。」"}]}, {"p": ["正如每顆石頭都有不同的特質與價值那般，各位也擁有自身的特質，都是珍貴的人，是獨一無二又珍貴的人作品。願各位都能向　神懇求並詢問自己是哪方面的作品，進而締造特別的故事。"]}], "audio": "https://grand-pasca-8d267f.netlify.app/audio/koppulso-bawi.zh.v1.m4a", "audioDur": 107.9}}, "audio": "/sayeon/stones/audio/18-guide.mp3", "audioDur": 103.5}];

